      const recs=eco.records;
      console.log('\nseed',seed,'ticks',eco.tick,'events',eco.events.map(e=>e.kind+'@'+e.gen).join(','),'births',eco.births,'time',Date.now()-t0);
      console.log(recs.map(r=>`${r.gen}:${r.plant}/${r.prey}/${r.pred}`).join(' '));
      const stats=eco.traitStats('prey',eco.prey); const st2=eco.traitStats('pred',eco.pred);
      console.log('prey genes', Object.fromEntries(GENE_KEYS.map(k=>[k, stats[k]])));
      console.log('pred genes', Object.fromEntries(GENE_KEYS.map(k=>[k, st2[k]])));
    }
  }
}
EOF
