'use strict';
// ─── deterministic PRNG ─────────────────────────────────────────────
function hashSeed(seed) {
  let h = 2166136261 >>> 0;
  const s = String(seed);
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  h ^= h >>> 16; h = Math.imul(h, 2246822507); h ^= h >>> 13; h = Math.imul(h, 3266489909); h ^= h >>> 16;
  return h >>> 0;
}
function mulberry32(a) {
  return function() {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const W = 180, H = 120, GEN_TICKS = 72;
const TAU = Math.PI * 2;
const clamp = (v,a,b)=>v<a?a:v>b?b:v;
const lerp = (a,b,t)=>a+(b-a)*t;
const distance2 = (ax,ay,bx,by)=>{ const dx=ax-bx, dy=ay-by; return dx*dx+dy*dy; };

const SPECIES = {
  flora: { label: 'Flora', common: 'Glass moss', latin: 'Muscus vitreus', color: '#71824e' },
  prey: { label: 'Grazer', common: 'Meadow grazer', latin: 'Herbivora campestris', color: '#b6743b' },
  pred: { label: 'Kite', common: 'Ember kite', latin: 'Milvus rubra', color: '#7f3731' }
};
const GENE_KEYS = ['speed','vision','metabolism','repro'];
const GENE_META = {
  speed: { label:'Speed', unit:'cells/tick', short:'SPD' },
  vision:{ label:'Vision', unit:'cells', short:'VIS' },
  metabolism:{ label:'Metabolism', unit:'×', short:'MET' },
  repro:{ label:'Repro. threshold', unit:'energy', short:'RPR' }
};
const GENE_RANGES = {
  prey: { speed:[0.42,2.05], vision:[2.2,12.5], metabolism:[0.55,1.95], repro:[65,140] },
  pred: { speed:[0.55,2.6], vision:[2.8,14.5], metabolism:[0.7,2.1], repro:[65,160] }
};
const INIT_GENE = { prey: { speed:.48, vision:.48, metabolism:.5, repro:.46 }, pred:{ speed:.56, vision:.52, metabolism:.52, repro:.5 } };

function genePheno(species,key,g) { const r=GENE_RANGES[species][key]; return lerp(r[0],r[1],clamp(g,0,1)); }

class Ecosystem {
  constructor(opts={}) {
    this.opts = Object.assign({ seed:1847, mutation:0.045, regrowth:1.0, generations:20, intervals:{drought:10,blight:14,frost:12} }, opts);
    this.seed = String(this.opts.seed);
    this.rng = mulberry32(hashSeed(this.seed));
    this.mutation = this.opts.mutation;
    this.regrowth = this.opts.regrowth;
    this.targetGenerations = this.opts.generations;
    this.tick = 0;
    this.generation = 0;
    this.done = false;
    this.plants = new Uint8Array(W*H);
    this.plantCells = [];
    this.plantPos = new Int32Array(W*H).fill(-1);
    this.prey = [];
    this.pred = [];
    this.nextId = 1;
    this.records = [];
    this.events = [];
    this.births = {prey:0,pred:0};
    this.kills = 0; this.preyStarved=0; this.predStarved=0;
    this.deaths = {prey:0,pred:0};
    this.active = [];
    this.intervals = Object.assign({drought:10,blight:14,frost:12}, this.opts.intervals);
    this.nextDue = {};
    this.telemetry = { plant:[], spread:[], prey:[], pred:[] };
    this.plantVersion = 0;
    this.lastEvent = null;
    this.spatial = { preyBuckets: new Map(), predBuckets: new Map() };
    this._gaussNext = null;
    this.seedInitial();
    this.scheduleInitial();
    this.recordGeneration();
    this.sampleTelemetry();
  }
  rand(){ return this.rng(); }
  randInt(a,b){ return a + Math.floor(this.rng()*(b-a+1)); }
  gauss(){
    if (this._gaussNext !== null) { const v=this._gaussNext; this._gaussNext=null; return v; }
    let u=0,v=0; while(u===0) u=this.rng(); while(v===0) v=this.rng();
    const m=Math.sqrt(-2*Math.log(u));
    this._gaussNext=m*Math.sin(TAU*v);
    return m*Math.cos(TAU*v);
  }
  sampleGauss(){ // deterministic, avoids caching complexity
    let s=0; for(let i=0;i<6;i++) s+=this.rng();
    return (s-3)/Math.sqrt(0.5);
  }
  seedInitial() {
    const r=this.rng;
    // clustered moss
    const targetCoverage = 0.22;
    const target = Math.floor(W*H*targetCoverage);
    let patches = 92;
    const centers=[];
    for(let i=0;i<patches;i++){
      const cx = r()*W, cy = r()*H, rad = 3 + r()*9;
      centers.push([cx,cy,rad]);
    }
    let guard=0;
    while(this.plantCells.length<target && guard++<target*8){
      const p=centers[Math.floor(r()*centers.length)];
      const ang=r()*TAU, rr=Math.sqrt(r())*p[2];
      const x=Math.floor(p[0]+Math.cos(ang)*rr), y=Math.floor(p[1]+Math.sin(ang)*rr);
      if(x<0||y<0||x>=W||y>=H) continue;
      const idx=y*W+x;
      if(!this.plants[idx] && r()<0.62) this.addPlant(idx);
    }
    // a few additional scattered spores
    for(let i=0;i<110;i++) { const x=Math.floor(r()*W),y=Math.floor(r()*H),idx=y*W+x; if(!this.plants[idx]) this.addPlant(idx); }
    this.prey = [];
    this.pred = [];
    this.nextId=1;
    for(let i=0;i<58;i++){
      const a=this.makeAnimal('prey', r()*W, r()*H, 45+r()*40);
      this.prey.push(a);
    }
    for(let i=0;i<18;i++){
      const a=this.makeAnimal('pred', r()*W, r()*H, 72+r()*58);
      this.pred.push(a);
    }
  }
  makeAnimal(species, x, y, energy, genes=null){
    const g={};
    const base=INIT_GENE[species];
    for(const key of GENE_KEYS){
      g[key] = genes ? clamp(genes[key] + (this.sampleGauss()*this.mutation),0,1) : clamp(base[key] + (this.rng()-0.5)*0.16,0.03,0.97);
    }
    const a = {
      id:this.nextId++, species, x, y, prevX:x, prevY:y,
