.weather-head{display:flex;align-items:center;justify-content:space-between;gap:12px;font-family:var(--mono);font-size:7px;letter-spacing:.15em;text-transform:uppercase;color:var(--ink-soft);line-height:1.2}
.weather-title{color:var(--ink)}
.weather-sub{color:var(--ink-soft);opacity:.72;letter-spacing:.1em;text-transform:none;font-size:6.5px}
.weather-keys{display:flex;align-items:center;gap:10px;margin-left:auto;white-space:nowrap}
.weather-keys .wkey{display:inline-flex;align-items:center;gap:4px}
.weather-keys .wkey::before{content:"";width:6px;height:1px;background:currentColor;box-shadow:0 0 0 0 transparent}
.weather-keys .kflora{color:var(--flora)}
.weather-keys .kprey{color:var(--prey)}
.weather-keys .kpred{color:var(--pred)}
.weather-keys .kevent{color:var(--ink-soft);border-left:1px solid var(--ink-ghost);padding-left:9px}
.weather-keys .kevent::before{width:3px;height:7px;background:var(--ink-faint)}
#timelineCanvas{display:block;width:100%;height:100%;min-height:37px}
.report-reopen{
  position:absolute;right:24px;bottom:24px;z-index:9;
  background:rgba(23,36,29,.93);color:var(--panel-text);border:1px solid rgba(224,198,150,.6);
  font-family:var(--mono);font-size:7px;letter-spacing:.17em;text-transform:uppercase;padding:7px 10px;
  box-shadow:0 5px 15px rgba(25,33,23,.2);transition:background .2s;
}
.report-reopen:hover{background:var(--ink)}
.report-reopen span{color:var(--brass-hi);padding-left:6px}

/* ── instrument drawer ──────────────────────────────────────────────────── */
.app.drawer-collapsed{--drawerW:57px}
.instrument-drawer{
  position:relative;min-height:0;min-width:0;display:flex;flex-direction:column;
  background:
    radial-gradient(90% 60% at 10% 0%,rgba(71,96,78,.2),transparent 55%),
    linear-gradient(148deg,#1b2b23 0%,#15211b 58%,#192820 100%);
  color:var(--panel-text);border:1px solid #3b4b3f;border-radius:2px;
  box-shadow:0 18px 36px rgba(34,31,20,.24),inset 0 0 0 1px rgba(238,225,199,.04);
  transition:width .38s var(--ease),flex-basis .38s var(--ease);
}
.instrument-drawer::before{
  content:"";position:absolute;inset:0;pointer-events:none;background-image:var(--grain);opacity:.11;mix-blend-mode:screen;border-radius:inherit;
}
.instrument-drawer::after{
  content:"";position:absolute;left:4px;top:6px;bottom:6px;width:1px;background:linear-gradient(transparent,rgba(224,198,150,.35) 10%,rgba(224,198,150,.1) 90%,transparent);pointer-events:none;
}
.drawer-head{
  flex:0 0 auto;padding:13px 14px 12px 17px;display:flex;align-items:center;justify-content:space-between;gap:9px;
  border-bottom:1px solid var(--panel-line);position:relative;z-index:1;
}
.drawer-title-block{min-width:0}
.drawer-eyebrow{display:block;font-family:var(--mono);font-size:6.5px;letter-spacing:.23em;text-transform:uppercase;color:var(--brass-hi);opacity:.8}
.drawer-title{display:block;margin-top:3px;font-weight:400;font-size:19px;line-height:1;letter-spacing:-.01em;color:var(--paper-hi);font-style:italic}
.drawer-title small{font-family:var(--mono);font-style:normal;font-size:6.5px;letter-spacing:.15em;color:var(--panel-muted);text-transform:uppercase;margin-left:6px;vertical-align:2px}
.icon-btn{
  width:27px;height:27px;flex:0 0 auto;display:grid;place-items:center;border:1px solid rgba(225,205,167,.27);
  color:var(--panel-text);background:rgba(255,255,255,.025);transition:background .2s,border-color .2s;
}
.icon-btn:hover{background:rgba(224,198,150,.12);border-color:rgba(224,198,150,.58)}
.icon-btn svg{width:12px;height:12px;stroke:currentColor;fill:none;stroke-width:1.1}
.drawer-body{
  min-height:0;overflow-y:auto;overflow-x:hidden;padding:4px 15px 8px 17px;position:relative;z-index:1;
  scrollbar-width:thin;scrollbar-color:rgba(224,198,150,.35) transparent;
}
.drawer-body::-webkit-scrollbar{width:4px}
.drawer-body::-webkit-scrollbar-thumb{background:rgba(224,198,150,.27);border-radius:5px}
.drawer-section{padding:10px 0 3px}
.section-heading{display:flex;align-items:center;gap:8px;margin:0 0 2px;color:var(--panel-muted)}
.section-heading .num{
  display:inline-grid;place-items:center;width:16px;height:16px;border:1px solid rgba(224,198,150,.27);border-radius:50%;
  font-family:var(--mono);font-size:6.5px;color:var(--brass-hi);letter-spacing:0
}
.section-heading h2{margin:0;font-family:var(--mono);font-size:7px;font-weight:400;letter-spacing:.18em;text-transform:uppercase;color:var(--panel-muted);white-space:nowrap}
.section-heading .rule{height:1px;flex:1;background:var(--panel-line)}
.control{padding:9px 0 8px;border-bottom:1px dashed rgba(225,205,167,.10)}
.control:last-child{border-bottom:0;padding-bottom:3px}
.control-head{display:flex;align-items:baseline;justify-content:space-between;gap:8px;min-height:17px}
.control-head label,.control-head .control-name{font-family:var(--serif);font-size:12.5px;line-height:1.1;letter-spacing:.01em;color:var(--paper-hi);cursor:default}
.control-head .unit{font-family:var(--mono);font-size:6.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--panel-muted);margin-left:4px}
.tip-mark{display:inline-grid;place-items:center;width:10px;height:10px;margin-left:5px;border:1px solid rgba(224,198,150,.34);border-radius:50%;font-family:var(--mono);font-size:6px;color:var(--brass-hi);vertical-align:1px;opacity:.8}
.readout{font-family:var(--mono);font-size:9px;letter-spacing:.02em;color:var(--brass-hi);white-space:nowrap;font-variant-numeric:tabular-nums}
.readout .readout-unit{color:var(--panel-muted);font-size:6.5px;letter-spacing:.07em;margin-left:2px;text-transform:uppercase}
.control-main{display:grid;grid-template-columns:minmax(0,1fr) 72px;gap:11px;align-items:end;margin-top:6px}
.range-wrap{min-width:0;padding-top:2px}
.range{
  -webkit-appearance:none;appearance:none;display:block;width:100%;height:20px;margin:0;padding:0;background:transparent;cursor:crosshair;
  --pct:50%;
}
.range::-webkit-slider-runnable-track{height:2px;border-radius:1px;background:linear-gradient(to right,var(--brass) 0 var(--pct),rgba(225,205,167,.20) var(--pct) 100%)}
.range::-moz-range-track{height:2px;border-radius:1px;background:rgba(225,205,167,.20)}
.range::-moz-range-progress{height:2px;border-radius:1px;background:var(--brass)}
.range::-webkit-slider-thumb{
  -webkit-appearance:none;appearance:none;width:11px;height:11px;margin-top:-4.5px;background:var(--brass-hi);
  border:1px solid #4b3f2d;border-radius:1px;transform:rotate(45deg);box-shadow:0 0 0 2px rgba(23,36,29,.8),0 0 0 3px rgba(224,198,150,.08);
  transition:box-shadow .18s,background .18s;
}
.range::-moz-range-thumb{width:9px;height:9px;background:var(--brass-hi);border:1px solid #4b3f2d;border-radius:1px;transform:rotate(45deg);box-shadow:0 0 0 2px rgba(23,36,29,.8)}
.range:hover::-webkit-slider-thumb,.range:focus-visible::-webkit-slider-thumb{box-shadow:0 0 0 2px rgba(23,36,29,.9),0 0 0 4px rgba(224,198,150,.22)}
.range:focus-visible{outline:1px solid rgba(224,198,150,.65);outline-offset:3px}
.range:active::-webkit-slider-thumb{background:#fff0c9}
.range-scale{display:flex;justify-content:space-between;font-family:var(--mono);font-size:6px;line-height:1;color:var(--panel-muted);letter-spacing:.08em;text-transform:uppercase;opacity:.72;padding-top:1px}
.spark-box{min-width:0;min-height:35px;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;border-left:1px solid rgba(225,205,167,.15);padding-left:8px;opacity:.93}
.spark-box canvas{display:block;width:100%;height:22px}
.spark-box .spark-label{display:block;margin-top:2px;font-family:var(--mono);font-size:5.6px;line-height:1;letter-spacing:.06em;color:var(--panel-muted);text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.control-pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;border-bottom:1px dashed rgba(225,205,167,.10)}
.control-pair .control{padding-top:9px;padding-bottom:8px;border-bottom:0;min-width:0}
.control-pair .control-main{display:block;margin-top:6px}
.control-pair .spark-box{min-height:25px;border-left:0;padding-left:0;border-top:1px solid rgba(225,205,167,.11);padding-top:4px;margin-top:3px}
.control-pair .spark-box canvas{height:15px}
.stepper{display:grid;grid-template-columns:20px minmax(0,1fr) 20px;height:27px;border:1px solid rgba(225,205,167,.24);background:rgba(4,12,8,.21);margin-top:4px}
.stepper button{display:grid;place-items:center;color:var(--brass-hi);font-family:var(--mono);font-size:13px;line-height:1;transition:background .15s,color .15s}
.stepper button:hover{background:rgba(224,198,150,.13);color:#fff1cc}
.stepper button:first-child{border-right:1px solid rgba(225,205,167,.14)}
.stepper button:last-child{border-left:1px solid rgba(225,205,167,.14)}
.stepper input{width:100%;min-width:0;border:0;background:transparent;color:var(--paper-hi);text-align:center;font-family:var(--mono);font-size:11px;letter-spacing:.04em;font-variant-numeric:tabular-nums;padding:0}
.stepper input:focus{outline:1px solid rgba(224,198,150,.55);outline-offset:-2px;background:rgba(224,198,150,.07)}
.stepper input::-webkit-inner-spin-button,.stepper input::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}
.stepper input[type=number]{-moz-appearance:textfield;appearance:textfield}
.mini-head-actions{display:flex;align-items:center;gap:4px}
.mini-action{
  display:grid;place-items:center;width:15px;height:15px;border:1px solid rgba(225,205,167,.2);
  font-family:var(--mono);font-size:7px;color:var(--brass-hi);transition:background .15s
}
.mini-action:hover{background:rgba(224,198,150,.14)}
.speed-control{padding-bottom:5px}
.speed-flex{display:grid;grid-template-columns:96px minmax(0,1fr);gap:15px;align-items:center;margin-top:5px}
.dial{
  width:94px;height:94px;border-radius:50%;position:relative;touch-action:none;cursor:grab;
  background:radial-gradient(circle at 40% 32%,#2b3d32 0%,#1c2c23 46%,#111c16 100%);
  border:1px solid rgba(224,198,150,.5);
  box-shadow:0 5px 11px rgba(0,0,0,.28),inset 0 0 0 4px rgba(0,0,0,.13),inset 0 0 18px rgba(0,0,0,.4);
  outline:none;
}
.dial:active{cursor:grabbing}
.dial:focus-visible{outline:1px solid var(--brass-hi);outline-offset:4px;box-shadow:0 0 0 5px rgba(224,198,150,.11),0 5px 11px rgba(0,0,0,.28)}
.dial::before{
  content:"";position:absolute;inset:9px;border-radius:50%;
  background:repeating-conic-gradient(from -135deg,rgba(224,198,150,.76) 0 .7deg,transparent .7deg 12deg);
  -webkit-mask:radial-gradient(circle,transparent 63%,#000 64% 67%,transparent 68%);
  mask:radial-gradient(circle,transparent 63%,#000 64% 67%,transparent 68%);
  opacity:.7;pointer-events:none;
}
.dial::after{content:"";position:absolute;inset:13px;border:1px solid rgba(224,198,150,.14);border-radius:50%;pointer-events:none}
.dial-arc{position:absolute;inset:6px;border-radius:50%;border:1px dashed rgba(224,198,150,.16);pointer-events:none}
.dial-needle{
  position:absolute;left:50%;bottom:50%;width:1px;height:31px;background:linear-gradient(to top,rgba(224,198,150,.55),var(--brass-hi));
  transform-origin:50% 100%;transform:rotate(0deg);pointer-events:none;
  box-shadow:0 0 5px rgba(224,198,150,.25);
}
.dial-needle::before{content:"";position:absolute;left:-2px;top:-1px;width:5px;height:5px;border-radius:50%;background:var(--brass-hi);box-shadow:0 0 7px rgba(224,198,150,.6)}
.dial-cap{
  position:absolute;left:50%;top:50%;width:17px;height:17px;transform:translate(-50%,-50%);
  border-radius:50%;border:1px solid rgba(224,198,150,.55);background:radial-gradient(circle at 40% 35%,#435749,#1b2b22 70%);
  box-shadow:0 1px 2px rgba(0,0,0,.45);pointer-events:none;
}
.dial-cap::after{content:"";position:absolute;inset:5px;border-radius:50%;background:var(--brass);opacity:.7}
.dial-read{position:absolute;left:0;right:0;bottom:13px;text-align:center;font-family:var(--mono);font-size:6px;letter-spacing:.09em;text-transform:uppercase;color:var(--panel-muted);pointer-events:none}
.speed-info{min-width:0}
.speed-value{display:block;font-family:var(--serif);font-size:26px;font-weight:400;line-height:.9;letter-spacing:-.04em;color:var(--paper-hi);white-space:nowrap}
.speed-value small{font-family:var(--mono);font-size:9px;letter-spacing:.02em;color:var(--brass-hi);margin-left:2px;vertical-align:4px}
.speed-unit{display:block;margin-top:4px;font-family:var(--mono);font-size:6.5px;line-height:1.3;letter-spacing:.06em;color:var(--panel-muted);text-transform:uppercase}
.speed-info .spark-box{border-left:0;padding-left:0;margin-top:5px;min-height:30px}
.speed-info .spark-box canvas{height:18px}
.weather-control{padding:8px 0 7px}
.weather-control .control-main{grid-template-columns:minmax(0,1fr) 57px;gap:8px;margin-top:4px}
.weather-control .control-head label{font-size:12px}
.cat-name{display:inline-flex;align-items:center;gap:6px}
.cat-glyph{width:9px;height:9px;display:inline-block;position:relative;flex:0 0 auto;color:var(--cat-color,var(--brass))}
.cat-glyph::before,.cat-glyph::after{content:"";position:absolute;background:currentColor}
.cat-glyph::before{left:4px;top:0;width:1px;height:9px;transform:rotate(28deg)}
.cat-glyph::after{left:0;top:4px;width:9px;height:1px;transform:rotate(-28deg)}
.weather-control .spark-box{border-left:0;padding-left:0;min-height:30px}
.weather-control .spark-box canvas{height:18px}
.weather-next{display:block;text-align:right;margin-top:2px;font-family:var(--mono);font-size:5.6px;letter-spacing:.05em;text-transform:uppercase;color:var(--panel-muted);white-space:nowrap}
.toggle-list{margin-top:3px}
.toggle-row{
  display:grid;grid-template-columns:minmax(0,1fr) 28px;align-items:center;gap:12px;
  padding:7px 0;border-bottom:1px dashed rgba(225,205,167,.08);cursor:pointer;position:relative;
}
.toggle-row:last-child{border-bottom:0}
.toggle-copy strong{display:block;font-family:var(--serif);font-size:11.5px;font-weight:400;line-height:1.15;color:var(--paper-hi)}
.toggle-copy small{display:block;margin-top:2px;font-family:var(--mono);font-size:5.7px;letter-spacing:.06em;color:var(--panel-muted);text-transform:uppercase;line-height:1.3}
.toggle-row input{position:absolute;opacity:0;width:1px;height:1px;pointer-events:none}
.toggle-track{
  width:28px;height:15px;border:1px solid rgba(225,205,167,.3);background:rgba(3,10,6,.27);border-radius:10px;position:relative;
  transition:background .22s,border-color .22s;pointer-events:none;
}
.toggle-track::after{
  content:"";position:absolute;left:2px;top:2px;width:9px;height:9px;border-radius:50%;background:var(--panel-muted);
  transition:transform .22s var(--ease),background .22s;
}
.toggle-row input:checked + .toggle-track{background:rgba(181,148,97,.23);border-color:rgba(224,198,150,.65)}
.toggle-row input:checked + .toggle-track::after{transform:translateX(13px);background:var(--brass-hi)}
.toggle-row input:focus-visible + .toggle-track{outline:1px solid var(--brass-hi);outline-offset:4px}
.drawer-foot{
  flex:0 0 auto;padding:10px 15px 11px 17px;border-top:1px solid var(--panel-line);position:relative;z-index:1;
  background:linear-gradient(to bottom,rgba(0,0,0,.05),rgba(0,0,0,.13));
}
.transport{display:flex;gap:7px}
.transport-btn{
  flex:1;min-height:30px;display:flex;align-items:center;justify-content:space-between;gap:5px;
  border:1px solid rgba(225,205,167,.31);padding:0 8px;color:var(--paper-hi);
  font-family:var(--mono);font-size:6.5px;letter-spacing:.12em;text-transform:uppercase;
  transition:background .18s,border-color .18s,color .18s;
}
.transport-btn:hover{background:rgba(224,198,150,.12);border-color:rgba(224,198,150,.55)}
.transport-btn.primary{background:rgba(181,148,97,.13);border-color:rgba(224,198,150,.56)}
.transport-btn.primary:hover{background:rgba(181,148,97,.25)}
.transport-btn.ghost{flex:0 0 85px}
.transport-btn kbd{font-family:var(--mono);font-size:5.5px;color:var(--panel-muted);letter-spacing:.04em;border:0}
.transport-icon{width:8px;height:9px;position:relative;display:inline-block;flex:0 0 auto}
.transport-icon.pause::before,.transport-icon.pause::after{content:"";position:absolute;top:0;bottom:0;width:2px;background:var(--brass-hi)}
.transport-icon.pause::before{left:0}.transport-icon.pause::after{right:0}
.transport-icon.play{width:0;height:0;border-top:5px solid transparent;border-bottom:5px solid transparent;border-left:7px solid var(--brass-hi)}
.drawer-subfoot{margin-top:7px;display:flex;justify-content:space-between;gap:10px;font-family:var(--mono);font-size:5.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--panel-muted)}
.drawer-subfoot b{font-weight:400;color:var(--brass-hi)}
.drawer-collapsed-label{display:none}
.app.drawer-collapsed .drawer-head{padding:12px 0;justify-content:center}
.app.drawer-collapsed .drawer-head .drawer-title-block{display:none}
.app.drawer-collapsed .drawer-head .icon-btn{transform:rotate(180deg)}
.app.drawer-collapsed .drawer-body,.app.drawer-collapsed .drawer-foot{display:none}
.app.drawer-collapsed .drawer-collapsed-label{
  display:flex;flex:1;flex-direction:column;align-items:center;justify-content:center;gap:18px;
  writing-mode:vertical-rl;transform:rotate(180deg);font-family:var(--mono);font-size:7px;letter-spacing:.22em;text-transform:uppercase;color:var(--panel-muted);cursor:pointer;
}
.app.drawer-collapsed .drawer-collapsed-label strong{font-weight:400;color:var(--brass-hi)}
.app.drawer-collapsed .drawer-collapsed-label svg{width:13px;height:13px;stroke:var(--brass-hi);fill:none;stroke-width:1}
.drawer-fab,.drawer-scrim{display:none}
</style>
</head>
<body>
<div class="app" id="app" data-state="running">
  <header class="masthead">
    <div class="mast-meta">
      <div class="meta-left">
        <span>The Adler Collection</span><i></i><span>Vol. IV · Folio VII</span>
      </div>
      <div class="meta-right">
        <span>Observations on appetite &amp; heredity</span><i></i><span>Drawn from the glass</span>
      </div>
    </div>
    <div class="mast-main">
      <div class="plate-seal" aria-hidden="true"><span>PLATE<br><strong>VII</strong><br>AD 1887</span></div>
      <div class="title-block">
        <p class="kicker">A field study in three lives</p>
        <h1>The <em>Vivarium</em> Ledger</h1>
        <p class="subtitle">A closed meadow, observed generation by generation.</p>
      </div>
      <div class="run-panel">
        <div class="live-pill"><span class="live-dot" aria-hidden="true"></span><span id="statusText">Field active</span></div>
        <div class="gen-readout">
          <div class="gen-line"><strong id="genNow">00</strong><span>/</span><span id="genTotal">20</span></div>
          <span class="gen-sub">Generations observed</span>
          <div class="progress-track" aria-hidden="true"><span id="genProgress"></span></div>
        </div>
      </div>
    </div>
    <div class="ornament-overlay" aria-hidden="true"></div>
  </header>

  <main class="workspace">
    <aside class="field-notes" aria-label="Species key and field notes">
      <div class="side-head"><em>The cast</em><span>live census</span></div>

      <article class="species-card" style="--sp-color:var(--flora)">
        <div class="species-glyph" aria-hidden="true">
          <svg viewBox="0 0 32 36"><path d="M16 33V16M16 23C10 23 6 19 5 12c7 0 11 4 11 11Zm0-5c6 0 10-4 11-11-7 0-11 4-11 11Z" fill="none" stroke="currentColor" stroke-width="1.25" stroke-linecap="round" stroke-linejoin="round"/><circle cx="16" cy="10" r="1.8" fill="currentColor"/></svg>
        </div>
        <div>
          <div class="role">I · Flora</div>
          <h2>Glass moss</h2>
          <p class="latin">Muscus vitreus</p>
          <div class="census"><b id="floraCount">0</b><span>pips</span></div>
          <div class="trait-line">vegetative · clonal</div>
          <canvas class="mini-spark" id="sparkFlora" aria-hidden="true"></canvas>
        </div>
      </article>

      <article class="species-card" style="--sp-color:var(--prey)">
        <div class="species-glyph" aria-hidden="true">
          <svg viewBox="0 0 32 36"><ellipse cx="16" cy="17" rx="7.7" ry="9.4" fill="none" stroke="currentColor" stroke-width="1.25"/><path d="M11 9 7 3m14 6 4-6M8.5 15h-5m5 5h-5m20-5h5m-5 5h5M12 26l-3 6m11-6 3 6" fill="none" stroke="currentColor" stroke-width="1.05" stroke-linecap="round"/><circle cx="16" cy="14" r="2.1" fill="currentColor"/><circle cx="16" cy="21" r="1" fill="currentColor"/></svg>
        </div>
        <div>
          <div class="role">II · Prey</div>
