    note: 'Grazers sicken. The kites grow lean.'
  },
  frost: {
    label: 'Frost', letter: 'F', color: '#638b94',
    phrase: 'the glass turns cold', duration: 56,
    note: 'The meadow stills; movement slows.'
  }
};
const CAT_ORDER = ['drought', 'blight', 'frost'];

function genePheno(species, key, gene) {
  const range = GENE_RANGES[species][key];
  return lerp(range[0], range[1], clamp(gene, 0, 1));
}
function geneNormalized(species, key, value) {
  const range = GENE_RANGES[species][key];
  return clamp((value - range[0]) / (range[1] - range[0]), 0, 1);
}

class Ecosystem {
  constructor(opts = {}) {
    const defaults = {
      seed: 1847,
      mutation: 0.045,
      regrowth: 1.0,
      generations: 20,
      intervals: { drought: 10, blight: 14, frost: 12 },
      refugia: true
    };
    this.opts = Object.assign({}, defaults, opts);
    this.opts.intervals = Object.assign({}, defaults.intervals, opts.intervals || {});
    this.seed = String(this.opts.seed);
    this.rng = mulberry32(hashSeed(this.seed));
    this.mutation = clamp(Number(this.opts.mutation), 0, 0.16);
    this.regrowth = clamp(Number(this.opts.regrowth), 0.2, 3);
    this.targetGenerations = clamp(Math.round(Number(this.opts.generations) || 20), 1, 120);
    this.refugia = this.opts.refugia !== false;
    this.tick = 0;
    this.generation = 0;
    this.done = false;
    this.plants = new Uint8Array(WORLD_W * WORLD_H);
    this.plantCells = [];
    this.plantPos = new Int32Array(WORLD_W * WORLD_H).fill(-1);
    this.prey = [];
    this.pred = [];
    this.nextId = 1;
    this.records = [];
    this.events = [];
    this.refugiaEvents = [];
    this.births = { prey: 0, pred: 0 };
    this.deaths = { prey: 0, pred: 0 };
    this.kills = 0;
    this.active = [];
    this.lastEvent = null;
    this.intervals = {
      drought: clamp(Math.round(this.opts.intervals.drought), 0, 20),
      blight: clamp(Math.round(this.opts.intervals.blight), 0, 20),
      frost: clamp(Math.round(this.opts.intervals.frost), 0, 20)
    };
    this.nextDue = { drought: Infinity, blight: Infinity, frost: Infinity };
    this.telemetry = { plant: [], spread: [], prey: [], pred: [] };
    this.plantVersion = 0;
    this.archive = { prey: [], pred: [] };
    this.extinctAt = { prey: null, pred: null };
    this.seedInitial();
    this.scheduleInitial();
    this.updateArchive();
    this.recordGeneration();
    this.sampleTelemetry();
  }

  rand() { return this.rng(); }
  randInt(a, b) { return a + Math.floor(this.rng() * (b - a + 1)); }
  sampleGauss() {
    let s = 0;
    for (let i = 0; i < 6; i++) s += this.rng();
    return (s - 3) / Math.sqrt(0.5);
  }

  seedInitial() {
    const r = this.rng;
    const target = Math.floor(WORLD_W * WORLD_H * 0.22);
    const patches = 92;
    const centers = [];
    for (let i = 0; i < patches; i++) centers.push([r() * WORLD_W, r() * WORLD_H, 3 + r() * 9]);
    let guard = 0;
    while (this.plantCells.length < target && guard++ < target * 8) {
      const p = centers[Math.floor(r() * centers.length)];
      const angle = r() * TAU;
      const radius = Math.sqrt(r()) * p[2];
      const x = Math.floor(p[0] + Math.cos(angle) * radius);
      const y = Math.floor(p[1] + Math.sin(angle) * radius);
      if (x < 0 || y < 0 || x >= WORLD_W || y >= WORLD_H) continue;
      const idx = y * WORLD_W + x;
      if (!this.plants[idx] && r() < 0.62) this.addPlant(idx);
    }
    for (let i = 0; i < 110; i++) {
      const x = Math.floor(r() * WORLD_W);
      const y = Math.floor(r() * WORLD_H);
      const idx = y * WORLD_W + x;
      if (!this.plants[idx]) this.addPlant(idx);
    }
    this.prey = [];
    this.pred = [];
    this.nextId = 1;
    for (let i = 0; i < 58; i++) {
      this.prey.push(this.makeAnimal('prey', r() * WORLD_W, r() * WORLD_H, 45 + r() * 40));
    }
    for (let i = 0; i < 18; i++) {
      this.pred.push(this.makeAnimal('pred', r() * WORLD_W, r() * WORLD_H, 72 + r() * 58));
    }
  }

  makeAnimal(species, x, y, energy, genes = null) {
    const g = {};
    const base = INIT_GENE[species];
    for (const key of GENE_KEYS) {
      if (genes) {
        g[key] = clamp(genes[key] + this.sampleGauss() * this.mutation, 0, 1);
      } else {
        g[key] = clamp(base[key] + (this.rng() - 0.5) * 0.16, 0.03, 0.97);
      }
    }
    return {
      id: this.nextId++, species,
      x, y, prevX: x, prevY: y,
      genes: g,
      energy,
      age: this.randInt(0, species === 'pred' ? 22 : 26),
      cooldown: this.randInt(0, 22),
      eatCd: 0,
      angle: this.rng() * TAU,
      alive: true,
      sick: 0,
      bornAt: this.tick
    };
  }

  addPlant(idx) {
    if (this.plants[idx]) return;
    this.plants[idx] = 1;
    this.plantPos[idx] = this.plantCells.length;
    this.plantCells.push(idx);
    this.plantVersion++;
  }
  removePlant(idx) {
    if (!this.plants[idx]) return;
    const pos = this.plantPos[idx];
    const last = this.plantCells.pop();
    if (pos < this.plantCells.length) {
      this.plantCells[pos] = last;
      this.plantPos[last] = pos;
    }
    this.plants[idx] = 0;
    this.plantPos[idx] = -1;
    this.plantVersion++;
  }
  plantCoverage() { return this.plantCells.length / (WORLD_W * WORLD_H); }

  scheduleInitial() {
    const r = this.rng;
    const first = {
      drought: Math.max(4, Math.round(this.intervals.drought * 0.60) + (r() < 0.4 ? 0 : 1)),
      blight: Math.max(6, Math.round(this.intervals.blight * 0.78) + (r() < 0.4 ? 0 : 1)),
      frost: Math.max(5, Math.round(this.intervals.frost * 0.66) + (r() < 0.4 ? 0 : 1))
    };
    for (const kind of CAT_ORDER) {
      this.nextDue[kind] = this.intervals[kind] > 0 ? first[kind] : Infinity;
    }
  }

  setCatastropheInterval(kind, value) {
    const val = clamp(Math.round(value), 0, 20);
    this.intervals[kind] = val;
    if (val <= 0) { this.nextDue[kind] = Infinity; return; }
    const prior = [...this.events].reverse().find(e => e.kind === kind);
    let next = prior ? prior.gen + val : this.generation + Math.max(1, Math.round(val * 0.55));
    if (next <= this.generation) next = this.generation + Math.max(1, Math.round(val * 0.55));
    this.nextDue[kind] = next;
  }

  effects() {
    let plant = 1, speed = 1, repro = 1, extraCost = 0;
    for (const e of this.active) {
      const elapsed = this.tick - e.startTick;
      const remaining = e.endTick - this.tick;
      const fade = clamp(Math.min(elapsed, remaining, 10) / 10, 0, 1);
      if (e.kind === 'drought') { plant *= lerp(1, 0.42, fade); extraCost += 0.005 * fade; }
      if (e.kind === 'frost') { plant *= lerp(1, 0.55, fade); speed *= lerp(1, 0.78, fade); repro *= lerp(1, 0.78, fade); extraCost += 0.003 * fade; }
      if (e.kind === 'blight') { repro *= lerp(1, 0.64, fade); }
    }
    return { plant, speed, repro, extraCost };
  }

  plantGrowth() {
    const eff = this.effects();
    const coverage = this.plantCoverage();
    if (coverage > 0.82) return;
    const attempts = Math.max(0, 18 * this.regrowth * (1 - coverage / 0.86) * eff.plant);
    let count = Math.floor(attempts);
    if (this.rng() < attempts - count) count++;
    if (this.plantCells.length < 50 && this.rng() < 0.5) count += 3;
    for (let i = 0; i < count; i++) {
      let x, y;
      if (this.plantCells.length && this.rng() < 0.54) {
        const pi = this.plantCells[Math.floor(this.rng() * this.plantCells.length)];
        const px = pi % WORLD_W;
        const py = Math.floor(pi / WORLD_W);
        x = clamp(px + this.randInt(-2, 2), 0, WORLD_W - 1);
        y = clamp(py + this.randInt(-2, 2), 0, WORLD_H - 1);
      } else {
        x = Math.floor(this.rng() * WORLD_W);
        y = Math.floor(this.rng() * WORLD_H);
      }
      const idx = y * WORLD_W + x;
      if (!this.plants[idx]) this.addPlant(idx);
    }
  }

  findNearestPlant(x, y, radius) {
    let best = null, bestD = radius * radius;
    const x0 = Math.max(0, Math.floor(x - radius));
    const x1 = Math.min(WORLD_W - 1, Math.ceil(x + radius));
    const y0 = Math.max(0, Math.floor(y - radius));
    const y1 = Math.min(WORLD_H - 1, Math.ceil(y + radius));
    for (let yy = y0; yy <= y1; yy++) {
      const row = yy * WORLD_W;
      for (let xx = x0; xx <= x1; xx++) {
        const idx = row + xx;
        if (this.plants[idx]) {
          const dx = x - (xx + 0.5), dy = y - (yy + 0.5);
          const d = dx * dx + dy * dy;
          if (d < bestD) { bestD = d; best = { x: xx + 0.5, y: yy + 0.5, idx }; }
        }
      }
    }
    return best;
  }
  buildSpatial(animals) {
    const buckets = new Map();
    const cell = 6;
    for (const a of animals) {
      if (!a.alive) continue;
      const bx = Math.floor(a.x / cell);
      const by = Math.floor(a.y / cell);
      const key = by * 1000 + bx;
      let bucket = buckets.get(key);
      if (!bucket) { bucket = []; buckets.set(key, bucket); }
      bucket.push(a);
    }
    return { buckets, cell };
  }
  querySpatial(spatial, x, y, radius) {
    const out = [];
    const { buckets, cell } = spatial;
    const bx0 = Math.floor((x - radius) / cell);
    const bx1 = Math.floor((x + radius) / cell);
    const by0 = Math.floor((y - radius) / cell);
    const by1 = Math.floor((y + radius) / cell);
    for (let by = by0; by <= by1; by++) {
      for (let bx = bx0; bx <= bx1; bx++) {
        const bucket = buckets.get(by * 1000 + bx);
        if (bucket) for (const a of bucket) if (a.alive) out.push(a);
      }
    }
    return out;
  }
  nearestOf(spatial, x, y, radius) {
    let best = null, bestD = radius * radius;
    for (const a of this.querySpatial(spatial, x, y, radius)) {
      const dx = x - a.x, dy = y - a.y;
      const d = dx * dx + dy * dy;
      if (d < bestD) { bestD = d; best = a; }
    }
    return best;
  }

  moveAnimal(a, dirX, dirY, speedFactor, speed) {
    let len = Math.hypot(dirX, dirY);
    if (len < 0.001) {
      a.angle += (this.rng() - 0.5) * 0.4;
      dirX = Math.cos(a.angle); dirY = Math.sin(a.angle); len = 1;
    }
    const step = speed * speedFactor;
    a.prevX = a.x; a.prevY = a.y;
    a.x += dirX / len * step;
    a.y += dirY / len * step;
    if (a.x < 1) { a.x = 1; a.angle = Math.PI - a.angle; }
    if (a.x > WORLD_W - 1) { a.x = WORLD_W - 1; a.angle = Math.PI - a.angle; }
    if (a.y < 1) { a.y = 1; a.angle = -a.angle; }
    if (a.y > WORLD_H - 1) { a.y = WORLD_H - 1; a.angle = -a.angle; }
    a.angle = Math.atan2(dirY, dirX);
  }
  wander(a, speedFactor, speed) {
    a.angle += (this.rng() - 0.5) * 0.55;
    this.moveAnimal(a, Math.cos(a.angle), Math.sin(a.angle), speedFactor, speed * 0.52);
  }
  makeChild(parent) {
    const child = this.makeAnimal(parent.species, parent.x + (this.rng() - 0.5) * 2, parent.y + (this.rng() - 0.5) * 2, parent.energy * 0.42, parent.genes);
    child.energy = parent.energy * 0.42;
    child.cooldown = 26;
    child.age = 0;
    return child;
  }

  updatePrey(spatialPred, eff, born) {
    const plantEnergy = 24;
    for (const a of this.prey) {
      if (!a.alive) continue;
      a.age++;
      if (a.cooldown > 0) a.cooldown--;
      if (a.sick > 0) a.sick--;
      if (a.eatCd > 0) a.eatCd--;
      const speed = genePheno('prey', 'speed', a.genes.speed);
      const vision = genePheno('prey', 'vision', a.genes.vision);
      const metab = genePheno('prey', 'metabolism', a.genes.metabolism);
      const threshold = genePheno('prey', 'repro', a.genes.repro);
      const cost = (0.020 + 0.025 * metab + 0.012 * speed + 0.0021 * vision) * (1 + eff.extraCost * 3 + (a.sick > 0 ? 0.28 : 0));
      a.energy -= cost;
      const predator = this.nearestOf(spatialPred, a.x, a.y, vision * 0.82 + 1.0);
      if (predator) {
        this.moveAnimal(a, a.x - predator.x, a.y - predator.y, eff.speed, speed * 0.98);
      } else {
        const plant = this.findNearestPlant(a.x, a.y, vision);
        if (plant) {
          const dx = plant.x - a.x, dy = plant.y - a.y;
          const d = Math.hypot(dx, dy);
          if (d < 0.95 && a.eatCd <= 0) {
            this.removePlant(plant.idx);
            a.energy = Math.min(180, a.energy + plantEnergy);
            a.eatCd = 21;
            a.angle += (this.rng() - 0.5) * 0.7;
          } else {
            this.moveAnimal(a, dx, dy, eff.speed, speed);
          }
        } else {
          this.wander(a, eff.speed, speed);
        }
      }
      if (a.energy <= 0 || a.age > 185 || (a.sick > 0 && this.rng() < 0.0026) || this.rng() < 0.000002) {
        a.alive = false; this.deaths.prey++; continue;
      }
      if (a.energy >= threshold && a.cooldown <= 0 && a.age > 16) {
        let chance = 0.055 * (1 + clamp((a.energy - threshold) / threshold, 0, 0.5));
        chance *= (a.sick > 0 ? 0.45 : 1) * eff.repro;
        chance *= clamp(this.plantCoverage() / 0.16, 0.08, 1);
        chance *= clamp(1 - this.prey.length / 900, 0.03, 1);
        if (this.rng() < chance) {
          const child = this.makeChild(a);
          a.energy *= 0.55;
          a.cooldown = 54;
          born.push(child);
          this.births.prey++;
        }
      }
      a.energy = Math.min(180, a.energy);
    }
    this.prey = this.prey.filter(a => a.alive);
    if (born.length) this.prey.push(...born);
  }

  updatePred(spatialPrey, eff, born) {
    for (const a of this.pred) {
      if (!a.alive) continue;
      a.age++;
      if (a.cooldown > 0) a.cooldown--;
      if (a.sick > 0) a.sick--;
      if (a.eatCd > 0) a.eatCd--;
      const speed = genePheno('pred', 'speed', a.genes.speed);
      const vision = genePheno('pred', 'vision', a.genes.vision);
      const metab = genePheno('pred', 'metabolism', a.genes.metabolism);
      const threshold = genePheno('pred', 'repro', a.genes.repro);
      const cost = (0.016 + 0.028 * metab + 0.010 * speed + 0.0012 * vision) * (1 + eff.extraCost * 2);
      a.energy -= cost;
      const prey = this.nearestOf(spatialPrey, a.x, a.y, vision);
      if (prey) {
        const dx = prey.x - a.x, dy = prey.y - a.y;
        const d = Math.hypot(dx, dy);
        if (d < 1.02 && a.eatCd <= 0) {
          prey.alive = false; this.deaths.prey++; this.kills++;
          a.energy = Math.min(220, a.energy + 20 + prey.energy * 0.66);
          a.eatCd = 20;
        } else {
          this.moveAnimal(a, dx, dy, eff.speed, speed * 1.12);
        }
      } else {
        this.wander(a, eff.speed, speed * 0.9);
      }
      if (a.energy <= 0 || a.age > 265 || this.rng() < 0.000002) {
        a.alive = false; this.deaths.pred++; continue;
      }
      if (a.energy >= threshold && a.cooldown <= 0 && a.age > 20) {
        let chance = 0.03 * (1 + clamp((a.energy - threshold) / threshold, 0, 0.5));
        chance *= eff.repro;
        chance *= clamp(1 - this.pred.length / 110, 0.02, 1);
        chance *= clamp((this.prey.length - 20) / 80, 0.03, 1);
        if (this.rng() < chance) {
          const child = this.makeChild(a);
          a.energy *= 0.54;
          a.cooldown = 64;
          born.push(child);
          this.births.pred++;
        }
      }
      a.energy = Math.min(220, a.energy);
    }
    this.pred = this.pred.filter(a => a.alive);
    if (born.length) this.pred.push(...born);
  }

  triggerCatastrophe(kind) {
    if (!CAT_META[kind]) return null;
    const duration = CAT_META[kind].duration;
    const e = { kind, gen: this.generation, startTick: this.tick, endTick: this.tick + duration, startGen: this.generation };
    this.events.push(e);
    this.active.push(e);
    this.lastEvent = { ...e };
    if (kind === 'drought') {
      const n = Math.floor(this.plantCells.length * 0.09);
      for (let i = 0; i < n && this.plantCells.length; i++) {
        this.removePlant(this.plantCells[Math.floor(this.rng() * this.plantCells.length)]);
      }
    } else if (kind === 'frost') {
      const n = Math.floor(this.plantCells.length * 0.13);
      for (let i = 0; i < n && this.plantCells.length; i++) {
        this.removePlant(this.plantCells[Math.floor(this.rng() * this.plantCells.length)]);
      }
    } else if (kind === 'blight') {
      for (const a of this.prey) {
        if (!a.alive) continue;
        if (this.rng() < 0.24) a.sick = duration + 5;
        if (this.rng() < 0.022) { a.alive = false; this.deaths.prey++; }
      }
      this.prey = this.prey.filter(a => a.alive);
    }
    return e;
  }

  triggerDueCatastrophes() {
    if (this.lastEvent && this.lastEvent.gen === this.generation) return;
    const due = CAT_ORDER.filter(kind => this.intervals[kind] > 0 && this.nextDue[kind] <= this.generation);
    due.sort((a, b) => this.nextDue[a] - this.nextDue[b]);
    if (!due.length) return;
    const kind = due[0];
    this.triggerCatastrophe(kind);
    this.nextDue[kind] += this.intervals[kind];
    if (this.nextDue[kind] <= this.generation + 1) {
      this.nextDue[kind] = this.generation + 1 + this.intervals[kind];
    }
  }

  maybeRefugia() {
    if (!this.refugia) return;
    let changed = false;
    if (this.prey.length === 0 && this.extinctAt.prey !== null) {
      this.restoreSpecies('prey', 8);
      changed = true;
    }
    if (this.pred.length === 0 && this.extinctAt.pred !== null && this.prey.length >= 20) {
      this.restoreSpecies('pred', 3);
      changed = true;
    }
    if (changed) {
      this.extinctAt.prey = this.prey.length ? null : this.extinctAt.prey;
      this.extinctAt.pred = this.pred.length ? null : this.extinctAt.pred;
    }
  }

  restoreSpecies(species, count) {
    const pool = this.archive[species];
    const fallback = INIT_GENE[species];
    const list = species === 'prey' ? this.prey : this.pred;
    for (let i = 0; i < count; i++) {
      const template = pool.length ? pool[this.randInt(0, pool.length - 1)] : fallback;
      const animal = this.makeAnimal(
        species,
        this.randInt(2, WORLD_W - 3),
        this.randInt(2, WORLD_H - 3),
        species === 'prey' ? 64 + this.rng() * 18 : 102 + this.rng() * 22,
        template
      );
      animal.age = this.randInt(0, 8);
      animal.cooldown = 0;
      list.push(animal);
    }
    this.refugiaEvents.push({ species, gen: this.generation, count });
  }

  step() {
    if (this.done) return;
    this.tick++;
    if (this.active.length) {
      this.active = this.active.filter(e => this.tick < e.endTick);
    }
    const eff = this.effects();
    this.plantGrowth();
    const spatialPred = this.buildSpatial(this.pred);
    const bornPrey = [];
    this.updatePrey(spatialPred, eff, bornPrey);
    const spatialPrey = this.buildSpatial(this.prey);
    const bornPred = [];
    this.updatePred(spatialPrey, eff, bornPred);
    if (this.tick % 6 === 0) this.sampleTelemetry();
    if (this.tick % GEN_TICKS === 0) {
      this.generation++;
      this.maybeRefugia();
      this.triggerDueCatastrophes();
      this.recordGeneration();
      if (this.generation >= this.targetGenerations) this.done = true;
    }
  }

  archiveSpecies(species) {
    const source = species === 'prey' ? this.prey : this.pred;
    if (!source.length) return;
    const picked = [];
    const count = Math.min(14, source.length);
    const stride = Math.max(1, Math.floor(source.length / count));
    for (let i = 0; i < source.length && picked.length < count; i += stride) {
      picked.push({ ...source[i].genes });
    }
    this.archive[species] = picked;
  }

  traitStats(species, animals) {
    const stats = {};
    for (const key of GENE_KEYS) {
      if (!animals.length) { stats[key] = { mean: null, sd: null }; continue; }
      let sum = 0, sum2 = 0;
      for (const a of animals) {
        const value = genePheno(species, key, a.genes[key]);
        sum += value;
        sum2 += value * value;
      }
      const mean = sum / animals.length;
      const sd = Math.sqrt(Math.max(0, sum2 / animals.length - mean * mean));
      stats[key] = { mean, sd };
    }
    return stats;
  }

  recordGeneration() {
    const rec = {
      gen: this.generation,
      plant: this.plantCells.length,
      prey: this.prey.length,
      pred: this.pred.length,
      traits: {
        prey: this.traitStats('prey', this.prey),
        pred: this.traitStats('pred', this.pred)
      },
      births: { ...this.births },
      deaths: { ...this.deaths },
      kills: this.kills,
      event: this.lastEvent && this.lastEvent.gen === this.generation ? this.lastEvent.kind : null
    };
    this.records.push(rec);
    if (this.prey.length === 0) {
      if (this.extinctAt.prey === null) this.extinctAt.prey = this.generation;
    } else this.extinctAt.prey = null;
    if (this.pred.length === 0) {
      if (this.extinctAt.pred === null) this.extinctAt.pred = this.generation;
    } else this.extinctAt.pred = null;
    this.archiveSpecies('prey');
    this.archiveSpecies('pred');
    this.sampleTelemetry();
  }

  sampleTelemetry() {
    let spread = 0, count = 0;
    for (const [species, animals] of [['prey', this.prey], ['pred', this.pred]]) {
      if (!animals.length) continue;
      const stats = this.traitStats(species, animals);
      for (const key of GENE_KEYS) {
        const st = stats[key];
        const range = GENE_RANGES[species][key][1] - GENE_RANGES[species][key][0];
        if (st.sd !== null) { spread += st.sd / range; count++; }
      }
    }
    const push = (arr, value) => { arr.push(value); if (arr.length > 90) arr.shift(); };
    push(this.telemetry.plant, this.plantCoverage() * 100);
    push(this.telemetry.spread, count ? spread / count : 0);
    push(this.telemetry.prey, this.prey.length);
    push(this.telemetry.pred, this.pred.length);
  }

  setTargetGenerations(value) {
    const target = clamp(Math.round(value), 1, 120);
    this.targetGenerations = target;
    if (this.generation >= target) this.done = true;
    else this.done = false;
  }

  nextDueFor(kind) { return this.nextDue[kind]; }
  countsAtGeneration(gen) {
    return this.records.find(r => r.gen === gen) || this.records[this.records.length - 1];
  }
}

function runHeadless(config = {}) {
  const opts = Object.assign({}, config);
  const eco = new Ecosystem(opts);
  let guard = 0;
  const maxTicks = GEN_TICKS * (opts.generations || eco.targetGenerations) + 500;
  while (!eco.done && guard++ < maxTicks) eco.step();
  return {
    seed: eco.seed,
    records: eco.records,
    events: eco.events,
    refugiaEvents: eco.refugiaEvents,
    births: { ...eco.births },
    deaths: { ...eco.deaths },
    final: {
      generation: eco.generation,
      plant: eco.plantCells.length,
      prey: eco.prey.length,
      pred: eco.pred.length,
      traits: {
        prey: eco.traitStats('prey', eco.prey),
        pred: eco.traitStats('pred', eco.pred)
      }
    }
  };
}

window.VIVARIUM = {
  Ecosystem,
  runHeadless,
  WORLD_W, WORLD_H, GEN_TICKS, BASE_TICKS_PER_SECOND,
  SPECIES, GENE_KEYS, GENE_META, GENE_RANGES, CAT_META, CAT_ORDER, genePheno, hashSeed, mulberry32
};

