function fitCanvas(canvas, cssWidth, cssHeight, dpr = Math.min(window.devicePixelRatio || 1, 2)) {
  const width = Math.max(1, Math.round(cssWidth * dpr));
  const height = Math.max(1, Math.round(cssHeight * dpr));
  if (canvas.width !== width || canvas.height !== height) {
    canvas.width = width;
    canvas.height = height;
  }
  const ctx = canvas.getContext('2d');
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  return { ctx, width: cssWidth, height: cssHeight, dpr };
}

function roundedRect(ctx, x, y, w, h, r) {
  const rr = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.arcTo(x + w, y, x + w, y + h, rr);
  ctx.arcTo(x + w, y + h, x, y + h, rr);
  ctx.arcTo(x, y + h, x, y, rr);
  ctx.arcTo(x, y, x + w, y, rr);
  ctx.closePath();
}

function formatCount(n) {
  if (n >= 10000) return Math.round(n / 100) / 10 + 'k';
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function drawSparkline(canvas, values, color, options = {}) {
  const rect = canvas.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const fit = fitCanvas(canvas, rect.width, rect.height, dpr);
  const ctx = fit.ctx;
  const w = fit.width, h = fit.height;
  ctx.clearRect(0, 0, w, h);
  ctx.strokeStyle = 'rgba(225,205,167,.17)';
  ctx.lineWidth = 0.7;
  ctx.beginPath(); ctx.moveTo(0, h - 3.5); ctx.lineTo(w, h - 3.5); ctx.stroke();
  const vals = (values || []).slice(-42);
  if (vals.length < 2) {
    ctx.fillStyle = 'rgba(224,198,150,.45)';
    ctx.beginPath(); ctx.arc(w - 3, h - 4, 1.5, 0, TAU); ctx.fill();
    return;
  }
  const min = Math.min(...vals), max = Math.max(...vals);
  const span = Math.max(0.0001, max - min);
  const pts = vals.map((v, i) => ({
    x: 1 + (i / (vals.length - 1)) * (w - 3),
    y: h - 5 - ((v - min) / span) * (h - 10)
  }));
  ctx.beginPath();
  ctx.moveTo(pts[0].x, h - 3.5);
  for (const p of pts) ctx.lineTo(p.x, p.y);
  ctx.lineTo(pts[pts.length - 1].x, h - 3.5);
  ctx.closePath();
  const grad = ctx.createLinearGradient(0, 0, 0, h);
  grad.addColorStop(0, color + '44');
  grad.addColorStop(1, color + '00');
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.beginPath();
  pts.forEach((p, i) => i ? ctx.lineTo(p.x, p.y) : ctx.moveTo(p.x, p.y));
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.stroke();
  const last = pts[pts.length - 1];
  ctx.fillStyle = color;
  ctx.beginPath(); ctx.arc(last.x, last.y, 1.65, 0, TAU); ctx.fill();
  if (options.playhead !== undefined) {
    const px = 1 + clamp(options.playhead, 0, 1) * (w - 3);
    ctx.strokeStyle = 'rgba(224,198,150,.32)';
    ctx.setLineDash([1.5, 2.5]);
    ctx.beginPath(); ctx.moveTo(px, 2); ctx.lineTo(px, h - 2); ctx.stroke();
    ctx.setLineDash([]);
  }
}

class WorldRenderer {
  constructor(app) {
    this.app = app;
    this.canvas = document.getElementById('worldCanvas');
    this.ctx = this.canvas.getContext('2d');
    this.wrap = document.getElementById('plateWrap');
    this.timeline = document.getElementById('timelineCanvas');
    this.timelineCtx = this.timeline.getContext('2d');
    this.lensCanvas = document.getElementById('lensCanvas');
    this.lensCtx = this.lensCanvas.getContext('2d');
    this.loupe = document.getElementById('loupe');
    this.bgCanvas = document.createElement('canvas');
    this.bgCtx = this.bgCanvas.getContext('2d');
    this.plantCanvas = document.createElement('canvas');
    this.plantCtx = this.plantCanvas.getContext('2d');
    this.w = 0; this.h = 0; this.dpr = 1;
    this.map = { x: 0, y: 0, w: 0, h: 0, scale: 1 };
    this.lastSeed = null;
    this.lastPlantDraw = 0;
    this.lastPlantVersion = -1;
    this.lastGrid = null;
    this.sprites = null;
    this.focus = null;
    this.focusSet = false;
    this.lensPos = null;
    this.pointerActive = false;
    this.cadence = [];
    this.cadenceLast = 0;
    this.hoverCat = null;
    this._resize = this.resize.bind(this);
    window.addEventListener('resize', this._resize);
    if (window.ResizeObserver) {
      this.ro = new ResizeObserver(this._resize);
      this.ro.observe(this.wrap);
      this.ro.observe(this.timeline);
    }
    const onMove = e => {
      const rect = this.wrap.getBoundingClientRect();
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;
      if (x < 0 || y < 0 || x > rect.width || y > rect.height) return;
      this.focus = { x, y };
      this.pointerActive = true;
      this.focusSet = true;
      this.app.revealLoupe();
    };
    this.wrap.addEventListener('pointermove', onMove, { passive: true });
    this.wrap.addEventListener('pointerdown', onMove, { passive: true });
    this.wrap.addEventListener('pointerleave', () => { this.pointerActive = false; });
    this.resize();
  }

  resize() {
    if (!this.wrap) return;
    const wr = this.wrap.getBoundingClientRect();
    const tr = this.timeline.getBoundingClientRect();
    this.w = Math.max(20, wr.width);
    this.h = Math.max(20, wr.height);
    this.dpr = Math.min(window.devicePixelRatio || 1, 2);
    this.canvas.width = Math.round(this.w * this.dpr);
    this.canvas.height = Math.round(this.h * this.dpr);
    this.canvas.style.width = this.w + 'px';
    this.canvas.style.height = this.h + 'px';
    this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.bgCanvas.width = this.canvas.width;
    this.bgCanvas.height = this.canvas.height;
    this.plantCanvas.width = this.canvas.width;
    this.plantCanvas.height = this.canvas.height;
    this.bgCtx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.plantCtx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    const padX = Math.max(26, this.w * 0.052);
    const padY = Math.max(23, this.h * 0.058);
    const scale = Math.min((this.w - padX * 2) / WORLD_W, (this.h - padY * 2) / WORLD_H);
    const mw = WORLD_W * scale, mh = WORLD_H * scale;
    this.map = { x: (this.w - mw) / 2, y: (this.h - mh) / 2, w: mw, h: mh, scale };
    this.timelineW = Math.max(30, tr.width);
    this.timelineH = Math.max(25, tr.height);
    this.timeline.width = Math.round(this.timelineW * this.dpr);
    this.timeline.height = Math.round(this.timelineH * this.dpr);
    this.timeline.style.width = this.timelineW + 'px';
    this.timeline.style.height = this.timelineH + 'px';
    this.timelineCtx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    const lr = this.lensCanvas.getBoundingClientRect();
    this.lensCanvas.width = Math.max(40, Math.round(lr.width * this.dpr));
    this.lensCanvas.height = Math.max(40, Math.round(lr.height * this.dpr));
    const lctx = this.lensCanvas.getContext('2d');
    lctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    this.lensW = lr.width; this.lensH = lr.height;
    this.plantSprites = null;
    this.buildSprites();
    this.buildBackground();
    this.plantVersion = -1;
    this.focusSet = false;
  }

  buildSprites() {
    const variants = [];
    const palette = [
      ['#63784a', '#8b9d62'],
      ['#758554', '#a2ad73'],
      ['#556b48', '#7e915f'],
      ['#81915c', '#afb87e']
    ];
    for (let v = 0; v < 4; v++) {
      const c = document.createElement('canvas');
      c.width = 32; c.height = 32;
      const x = c.getContext('2d');
      x.translate(16, 28);
      x.strokeStyle = palette[v][0];
      x.fillStyle = palette[v][1];
      x.lineWidth = 2.1;
      x.lineCap = 'round';
      x.beginPath(); x.moveTo(0, 0); x.quadraticCurveTo(-1.6, -9, 0.4, -17); x.stroke();
      x.beginPath(); x.moveTo(0, -8); x.quadraticCurveTo(-8, -15, -10, -21); x.quadraticCurveTo(-3, -17, 0, -8); x.fill();
      x.beginPath(); x.moveTo(0, -12); x.quadraticCurveTo(8, -18, 10, -24); x.quadraticCurveTo(3, -19, 0, -12); x.fill();
      x.beginPath(); x.moveTo(0, -18); x.quadraticCurveTo(-3, -25, -1, -29); x.quadraticCurveTo(3, -24, 0, -18); x.fill();
      x.globalAlpha = 0.55;
      x.fillStyle = palette[v][0];
      x.beginPath(); x.arc(4, -7, 1.1, 0, TAU); x.fill();
      x.beginPath(); x.arc(-5, -15, 0.9, 0, TAU); x.fill();
      variants.push(c);
    }
    this.sprites = variants;
  }

  buildBackground() {
    const ctx = this.bgCtx;
    const { w, h, map } = this;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = COLORS.paper;
    ctx.fillRect(0, 0, w, h);
    const glow = ctx.createRadialGradient(w * 0.27, h * 0.16, 10, w * 0.27, h * 0.16, w * 0.8);
    glow.addColorStop(0, 'rgba(255,250,235,.68)');
    glow.addColorStop(0.5, 'rgba(255,250,235,.1)');
    glow.addColorStop(1, 'rgba(99,79,49,.08)');
    ctx.fillStyle = glow;
    ctx.fillRect(0, 0, w, h);
    // faint paper fibers
    const paperRng = mulberry32(hashSeed('plate-paper-' + this.app.eco.seed));
    ctx.globalAlpha = 0.10;
    for (let i = 0; i < 160; i++) {
      const y = paperRng() * h;
      ctx.strokeStyle = paperRng() > 0.5 ? '#7f6a4a' : '#fff9e9';
      ctx.lineWidth = 0.45;
      ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y + (paperRng() - 0.5) * 2); ctx.stroke();
    }
    ctx.globalAlpha = 1;
    // map ground
    ctx.save();
    ctx.beginPath(); ctx.rect(map.x, map.y, map.w, map.h); ctx.clip();
    const ground = ctx.createLinearGradient(map.x, map.y, map.x + map.w, map.y + map.h);
    ground.addColorStop(0, 'rgba(221,222,194,.77)');
    ground.addColorStop(0.45, 'rgba(229,224,199,.74)');
    ground.addColorStop(1, 'rgba(224,218,190,.65)');
    ctx.fillStyle = ground; ctx.fillRect(map.x, map.y, map.w, map.h);
    // topographic paper contours
    const contourRng = mulberry32(hashSeed('contours-' + this.app.eco.seed));
    ctx.strokeStyle = 'rgba(99,117,79,.075)';
    ctx.lineWidth = 0.65;
    for (let i = 0; i < 8; i++) {
      const cx = map.x + contourRng() * map.w;
      const cy = map.y + contourRng() * map.h;
      const rx = 18 + contourRng() * map.w * 0.2;
      const ry = 12 + contourRng() * map.h * 0.23;
      for (let ring = 0; ring < 3; ring++) {
        ctx.beginPath();
        ctx.ellipse(cx, cy, rx * (1 + ring * 0.16), ry * (1 + ring * 0.16), contourRng() * 1.4, 0, TAU);
        ctx.stroke();
      }
    }
    // water stain / meadow wash
    const wash = ctx.createRadialGradient(map.x + map.w * .72, map.y + map.h * .64, 1, map.x + map.w * .72, map.y + map.h * .64, map.w * .28);
    wash.addColorStop(0, 'rgba(117,134,92,.12)');
    wash.addColorStop(1, 'rgba(117,134,92,0)');
    ctx.fillStyle = wash; ctx.fillRect(map.x, map.y, map.w, map.h);
    // graticule
    if (this.app.settings.grid) {
      ctx.strokeStyle = 'rgba(54,74,57,.12)';
      ctx.lineWidth = 0.55;
      ctx.setLineDash([1, 4]);
      for (let gx = 0; gx <= WORLD_W; gx += 15) {
        const px = map.x + (gx / WORLD_W) * map.w;
        ctx.beginPath(); ctx.moveTo(px, map.y + 2); ctx.lineTo(px, map.y + map.h - 2); ctx.stroke();
      }
      for (let gy = 0; gy <= WORLD_H; gy += 15) {
        const py = map.y + (gy / WORLD_H) * map.h;
        ctx.beginPath(); ctx.moveTo(map.x + 2, py); ctx.lineTo(map.x + map.w - 2, py); ctx.stroke();
      }
      ctx.setLineDash([]);
    }
    // cartographic annotations
    ctx.textBaseline = 'middle';
    ctx.fillStyle = 'rgba(40,58,43,.36)';
    ctx.font = `${Math.max(7, map.scale * 2.0)}px ${getComputedStyle(document.documentElement).getPropertyValue('--serif')}`;
    ctx.font = `${Math.max(7, map.scale * 1.7)}px "Iowan Old Style", "Palatino Linotype", "Bitstream Charter", Georgia, serif`;
    ctx.save();
    ctx.translate(map.x, map.y);
    ctx.globalAlpha = 0.66;
    const labels = [
      ['N. VERGE', 0.17, 0.13, -0.02],
      ['DEW HOLLOW', 0.68, 0.17, 0.02],
      ['THE GLASS LINE', 0.67, 0.79, -0.01],
      ['MOSS BANK', 0.23, 0.76, 0.015]
    ];
    for (const [text, xf, yf, rot] of labels) {
      ctx.save();
      ctx.translate(map.w * xf, map.h * yf);
      ctx.rotate(rot);
      ctx.font = `italic ${Math.max(7, map.scale * 1.8)}px "Iowan Old Style", "Palatino Linotype", "Bitstream Charter", Georgia, serif`;
      ctx.fillText(text, 0, 0);
      ctx.restore();
    }
    ctx.restore();
    // coordinates
    if (this.app.settings.grid) {
      ctx.fillStyle = 'rgba(40,58,43,.42)';
      ctx.font = `6px "JetBrains Mono", "Liberation Mono", monospace`;
      ctx.textAlign = 'center';
      for (let gx = 0; gx <= WORLD_W; gx += 30) {
        const px = map.x + (gx / WORLD_W) * map.w;
        ctx.fillText(String(gx).padStart(3, '0'), px, map.y - 7);
        ctx.fillText(String(gx).padStart(3, '0'), px, map.y + map.h + 9);
      }
      ctx.textAlign = 'left';
      for (let gy = 0; gy <= WORLD_H; gy += 30) {
        const py = map.y + (gy / WORLD_H) * map.h;
        ctx.fillText(String(gy).padStart(3, '0'), map.x - 20, py);
        ctx.textAlign = 'right';
        ctx.fillText(String(gy).padStart(3, '0'), map.x + map.w + 20, py);
        ctx.textAlign = 'left';
      }
    }
    // north mark
    const nx = map.x + map.w - 25;
    const ny = map.y + 25;
    ctx.strokeStyle = 'rgba(32,48,39,.52)';
    ctx.fillStyle = 'rgba(32,48,39,.68)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(nx, ny + 14); ctx.lineTo(nx, ny - 7); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(nx, ny - 10); ctx.lineTo(nx - 3.4, ny - 3); ctx.lineTo(nx + 3.4, ny - 3); ctx.closePath(); ctx.fill();
    ctx.font = '7px "JetBrains Mono", "Liberation Mono", monospace';
    ctx.textAlign = 'center';
    ctx.fillText('N', nx, ny - 16);
    // scale rule
    const sx = map.x + 24;
    const sy = map.y + map.h - 21;
    ctx.strokeStyle = 'rgba(32,48,39,.45)';
    ctx.fillStyle = 'rgba(32,48,39,.55)';
    ctx.lineWidth = 0.8;
    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(sx + 38, sy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(sx, sy - 3); ctx.lineTo(sx, sy + 3); ctx.moveTo(sx + 19, sy - 2); ctx.lineTo(sx + 19, sy + 2); ctx.moveTo(sx + 38, sy - 3); ctx.lineTo(sx + 38, sy + 3); ctx.stroke();
    ctx.font = '5.3px "JetBrains Mono", "Liberation Mono", monospace';
    ctx.textAlign = 'left';
    ctx.fillText('0', sx - 1, sy + 9);
    ctx.textAlign = 'right';
    ctx.fillText('20 DIV.', sx + 38, sy + 9);
    // graticule map frame
    ctx.strokeStyle = 'rgba(32,48,39,.43)';
    ctx.lineWidth = 0.9;
    ctx.strokeRect(map.x + 0.5, map.y + 0.5, map.w, map.h);
    ctx.strokeStyle = 'rgba(32,48,39,.18)';
    ctx.lineWidth = 0.6;
    ctx.strokeRect(map.x + 5.5, map.y + 5.5, map.w - 11, map.h - 11);
    // registration corners
    ctx.strokeStyle = 'rgba(32,48,39,.62)';
    ctx.lineWidth = 0.7;
    const corner = 8;
    for (const [x, y, dx, dy] of [
      [map.x, map.y, 1, 1], [map.x + map.w, map.y, -1, 1],
      [map.x, map.y + map.h, 1, -1], [map.x + map.w, map.y + map.h, -1, -1]
    ]) {
      ctx.beginPath();
      ctx.moveTo(x + dx * 12, y); ctx.lineTo(x, y); ctx.lineTo(x, y + dy * 12);
      ctx.stroke();
    }
    ctx.restore();
    // outside border hardware
    ctx.strokeStyle = 'rgba(32,48,39,.25)';
    ctx.lineWidth = 0.7;
    ctx.strokeRect(8.5, 8.5, w - 17, h - 17);
    this.lastSeed = this.app.eco.seed;
    this.lastGrid = this.app.settings.grid;
  }

  ensureBackground() {
    if (this.lastSeed !== this.app.eco.seed || this.lastGrid !== this.app.settings.grid) this.buildBackground();
  }

  drawPlantLayer() {
    const now = performance.now();
    if (this.lastPlantVersion === this.app.eco.plantVersion && this.lastPlantDraw && now - this.lastPlantDraw < 120) return;
    this.lastPlantVersion = this.app.eco.plantVersion;
    this.lastPlantDraw = now;
    const ctx = this.plantCtx;
    const { w, h, map } = this;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, w, h);
    if (!this.sprites) this.buildSprites();
    const size = Math.max(6, map.scale * 2.15);
    ctx.save();
    ctx.beginPath(); ctx.rect(map.x + 1, map.y + 1, map.w - 2, map.h - 2); ctx.clip();
    for (const idx of this.app.eco.plantCells) {
      const x = idx % WORLD_W;
      const y = (idx / WORLD_W) | 0;
      const hval = ((idx * 2654435761) ^ 0x9e3779b9) >>> 0;
      const variant = hval & 3;
      const jx = (((hval >>> 2) & 255) / 255 - 0.5) * 0.54;
      const jy = (((hval >>> 10) & 255) / 255 - 0.5) * 0.54;
      const px = map.x + (x + 0.5 + jx) * map.scale;
      const py = map.y + (y + 0.55 + jy) * map.scale;
      ctx.globalAlpha = 0.76 + ((hval >>> 18) & 63) / 300;
      ctx.drawImage(this.sprites[variant], px - size / 2, py - size * 0.82, size, size);
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  drawAnimals(eco, alpha, now) {
    const ctx = this.ctx;
    const map = this.map;
    const f = clamp(alpha, 0, 1);
    const preySize = clamp(map.scale * 0.92, 3.0, 5.2);
    const predSize = preySize * 1.46;
    ctx.save();
    ctx.beginPath(); ctx.rect(map.x, map.y, map.w, map.h); ctx.clip();
    for (const a of eco.prey) {
      const x = map.x + (lerp(a.prevX, a.x, f)) * map.scale;
      const y = map.y + (lerp(a.prevY, a.y, f)) * map.scale;
      this.drawGrazer(ctx, x, y, preySize, a, now);
    }
    for (const a of eco.pred) {
      const x = map.x + (lerp(a.prevX, a.x, f)) * map.scale;
      const y = map.y + (lerp(a.prevY, a.y, f)) * map.scale;
      this.drawKite(ctx, x, y, predSize, a, now);
    }
    ctx.restore();
  }

  drawGrazer(ctx, x, y, s, animal, now) {
    const newborn = animal.bornAt !== undefined && this.app.eco.tick - animal.bornAt < 12;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(animal.angle + Math.PI / 2);
    if (newborn) {
      ctx.strokeStyle = 'rgba(216,165,101,.36)';
      ctx.lineWidth = 0.7;
      ctx.beginPath(); ctx.arc(0, 0, s * 1.25, 0, TAU); ctx.stroke();
    }
    ctx.lineCap = 'round';
    ctx.strokeStyle = 'rgba(47,55,39,.72)';
    ctx.lineWidth = Math.max(0.6, s * 0.16);
    ctx.fillStyle = newborn ? COLORS.preyBright : COLORS.prey;
    const r = s * 0.55;
    ctx.beginPath(); ctx.ellipse(0, 0, r * 0.82, r, 0, 0, TAU); ctx.fill(); ctx.stroke();
    // antennae
    ctx.beginPath();
    ctx.moveTo(-r * 0.38, -r * 0.65);
    ctx.quadraticCurveTo(-s * 0.56, -s * 0.95, -s * 0.61, -s * 1.11);
    ctx.moveTo(r * 0.38, -r * 0.65);
    ctx.quadraticCurveTo(s * 0.56, -s * 0.95, s * 0.61, -s * 1.11);
    ctx.stroke();
    // legs
    ctx.beginPath();
    for (let i = -1; i <= 1; i++) {
      const yy = i * s * 0.22;
      ctx.moveTo(-r * 0.75, yy); ctx.lineTo(-r * 1.05, yy + s * 0.2);
      ctx.moveTo(r * 0.75, yy); ctx.lineTo(r * 1.05, yy + s * 0.2);
    }
    ctx.stroke();
    // eye / wing mark
    ctx.fillStyle = 'rgba(245,236,218,.82)';
    ctx.beginPath(); ctx.arc(-r * 0.23, -r * 0.28, Math.max(.55, s * 0.11), 0, TAU); ctx.fill();
    if (animal.sick > 0) {
      ctx.strokeStyle = 'rgba(119,90,123,.78)';
      ctx.lineWidth = 0.8;
      ctx.beginPath(); ctx.arc(0, 0, s * 0.85, 0, TAU); ctx.stroke();
      ctx.fillStyle = 'rgba(119,90,123,.95)';
      ctx.beginPath(); ctx.arc(r * 0.9, -r * 0.8, 0.9, 0, TAU); ctx.fill();
    }
    ctx.restore();
  }

  drawKite(ctx, x, y, s, animal, now) {
    const newborn = animal.bornAt !== undefined && this.app.eco.tick - animal.bornAt < 14;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(animal.angle + Math.PI / 2);
    if (newborn) {
      ctx.strokeStyle = 'rgba(185,97,82,.32)';
      ctx.lineWidth = 0.7;
      ctx.beginPath(); ctx.arc(0, 0, s * 1.2, 0, TAU); ctx.stroke();
    }
    ctx.fillStyle = newborn ? COLORS.predBright : COLORS.pred;
    ctx.strokeStyle = 'rgba(45,40,30,.77)';
    ctx.lineWidth = Math.max(0.65, s * 0.13);
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.7);
    ctx.lineTo(s * 0.58, -s * 0.1);
    ctx.lineTo(s * 0.22, s * 0.52);
    ctx.lineTo(0, s * 0.7);
    ctx.lineTo(-s * 0.22, s * 0.52);
    ctx.lineTo(-s * 0.58, -s * 0.1);
    ctx.closePath();
    ctx.fill(); ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, -s * 0.45); ctx.lineTo(0, s * 0.38);
    ctx.strokeStyle = 'rgba(244,234,213,.34)';
    ctx.lineWidth = 0.55;
    ctx.stroke();
    ctx.fillStyle = 'rgba(245,236,218,.78)';
    ctx.beginPath(); ctx.arc(0, -s * 0.17, Math.max(.55, s * 0.1), 0, TAU); ctx.fill();
    ctx.restore();
  }

  drawAtmosphere(eco, now) {
    if (!eco.active.length) return;
    const e = eco.active[eco.active.length - 1];
    const color = CAT_COLORS[e.kind];
    const elapsed = eco.tick - e.startTick;
    const remaining = e.endTick - eco.tick;
    const intensity = clamp(Math.min(elapsed, remaining, 12) / 12, 0, 1);
    const ctx = this.ctx;
    const { map } = this;
    ctx.save();
    ctx.beginPath(); ctx.rect(map.x, map.y, map.w, map.h); ctx.clip();
    const grad = ctx.createRadialGradient(map.x + map.w * .5, map.y + map.h * .38, 10, map.x + map.w * .5, map.y + map.h * .5, map.w * .58);
    if (e.kind === 'drought') {
      grad.addColorStop(0, `rgba(180,130,54,${.015 * intensity})`);
      grad.addColorStop(.7, `rgba(180,130,54,${.04 * intensity})`);
      grad.addColorStop(1, `rgba(131,91,37,${.11 * intensity})`);
    } else if (e.kind === 'blight') {
      grad.addColorStop(0, `rgba(119,90,123,0)`);
      grad.addColorStop(.6, `rgba(119,90,123,${.025 * intensity})`);
      grad.addColorStop(1, `rgba(87,59,88,${.1 * intensity})`);
    } else {
      grad.addColorStop(0, `rgba(99,139,148,${.022 * intensity})`);
      grad.addColorStop(.7, `rgba(99,139,148,${.045 * intensity})`);
      grad.addColorStop(1, `rgba(71,108,119,${.13 * intensity})`);
    }
    ctx.fillStyle = grad;
    ctx.fillRect(map.x, map.y, map.w, map.h);
    const t = now * 0.001;
    const count = e.kind === 'frost' ? 40 : 26;
    for (let i = 0; i < count; i++) {
      const seed = hashSeed(`${eco.seed}-${e.kind}-${e.gen}-${i}`);
      const rng = mulberry32(seed);
      const sx = map.x + ((rng() + t * (e.kind === 'frost' ? 0.007 : 0.012)) % 1) * map.w;
      const sy = map.y + ((rng() * 1.4 + t * (e.kind === 'frost' ? 0.013 : 0.005)) % 1) * map.h;
      ctx.globalAlpha = (0.18 + rng() * 0.4) * intensity;
      ctx.fillStyle = e.kind === 'drought' ? '#c0944f' : e.kind === 'blight' ? '#8b628c' : '#c5dfe1';
      const len = e.kind === 'frost' ? 1 : 3 + rng() * 6;
      ctx.fillRect(sx, sy, e.kind === 'drought' ? len : 1.1, e.kind === 'drought' ? 0.8 : 1.1);
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }

  drawGlassEdge() {
    const ctx = this.ctx;
    const { w, h } = this;
    const v = ctx.createRadialGradient(w * .5, h * .48, Math.min(w, h) * .25, w * .5, h * .48, Math.max(w, h) * .68);
    v.addColorStop(0, 'rgba(60,46,27,0)');
    v.addColorStop(.82, 'rgba(74,57,32,.025)');
    v.addColorStop(1, 'rgba(62,49,29,.12)');
    ctx.fillStyle = v;
    ctx.fillRect(0, 0, w, h);
  }

  computeLensPosition() {
    if (!this.focus) {
      const alive = [...this.app.eco.prey, ...this.app.eco.pred];
      if (alive.length) {
        let sx = 0, sy = 0;
        const n = Math.min(alive.length, 40);
        for (let i = 0; i < n; i++) { sx += alive[i].x; sy += alive[i].y; }
        this.focus = {
          x: this.map.x + (sx / n) / WORLD_W * this.map.w,
          y: this.map.y + (sy / n) / WORLD_H * this.map.h
        };
      } else {
        this.focus = { x: this.map.x + this.map.w * .57, y: this.map.y + this.map.h * .46 };
      }
      this.focusSet = true;
    }
    const f = this.focus;
    const lw = this.lensCanvas.getBoundingClientRect().width || 154;
    let left = f.x + 83;
    let top = f.y - 88;
    if (left + lw > this.w - 10) left = f.x - lw - 83;
    if (top < 10) top = f.y + 80;
    left = clamp(left, 10, this.w - lw - 10);
    top = clamp(top, 10, this.h - lw - 10);
    return { left, top, focusX: clamp(f.x, 10, this.w - 10), focusY: clamp(f.y, 10, this.h - 10) };
  }

  drawLens() {
    if (!this.app.settings.lens) { this.loupe.classList.add('is-hidden'); return; }
    this.loupe.classList.remove('is-hidden');
    const p = this.computeLensPosition();
    this.loupe.style.left = p.left + 'px';
    this.loupe.style.top = p.top + 'px';
    const lctx = this.lensCanvas.getContext('2d');
    const dpr = this.dpr;
    const zoom = 2.4;
    const srcW = this.lensW / zoom;
    const srcH = this.lensH / zoom;
    const sx = clamp((p.focusX - srcW / 2) * dpr, 0, this.canvas.width - srcW * dpr);
    const sy = clamp((p.focusY - srcH / 2) * dpr, 0, this.canvas.height - srcH * dpr);
    lctx.setTransform(1, 0, 0, 1, 0, 0);
    lctx.clearRect(0, 0, this.lensCanvas.width, this.lensCanvas.height);
    lctx.drawImage(this.canvas, sx, sy, srcW * dpr, srcH * dpr, 0, 0, this.lensCanvas.width, this.lensCanvas.height);
    // faint crosshair from the specimen's point of view
    lctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    lctx.strokeStyle = 'rgba(238,226,198,.45)';
    lctx.lineWidth = 0.5;
    lctx.beginPath();
    lctx.moveTo(this.lensW / 2 - 5, this.lensH / 2); lctx.lineTo(this.lensW / 2 + 5, this.lensH / 2);
    lctx.moveTo(this.lensW / 2, this.lensH / 2 - 5); lctx.lineTo(this.lensW / 2, this.lensH / 2 + 5);
    lctx.stroke();
  }

  drawTimeline(eco, settings) {
    const ctx = this.timelineCtx;
    const w = this.timelineW, h = this.timelineH;
    ctx.clearRect(0, 0, w, h);
    if (!w || !h) return;
    const padL = 3, padR = 3, padT = 10, padB = 12;
    const target = Math.max(1, eco.targetGenerations);
    const xFor = gen => padL + (gen / target) * (w - padL - padR);
    const records = eco.records;
    let maxVal = 10;
    for (const r of records) maxVal = Math.max(maxVal, r.plant, r.prey, r.pred);
    const maxExp = Math.max(1, Math.ceil(Math.log10(maxVal)));
    const yFor = value => {
      const t = Math.log10(Math.max(1, value)) / maxExp;
      return padT + (1 - t) * (h - padT - padB);
    };
    ctx.strokeStyle = 'rgba(32,48,39,.09)';
    ctx.lineWidth = 0.6;
    for (let e = 0; e <= maxExp; e++) {
      const y = padT + (1 - e / maxExp) * (h - padT - padB);
      ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(w - padR, y); ctx.stroke();
    }
    const currentGen = eco.generation + clamp(eco.tick % GEN_TICKS / GEN_TICKS, 0, 1);
    const live = {
      gen: currentGen,
      plant: eco.plantCells.length,
      prey: eco.prey.length,
      pred: eco.pred.length
    };
    const points = records.map(r => ({ gen: r.gen, plant: r.plant, prey: r.prey, pred: r.pred }));
    if (!eco.done) points.push(live);
    const series = [
      { key: 'plant', color: 'rgba(110,128,80,.8)', width: 1.1 },
      { key: 'prey', color: 'rgba(184,120,60,.9)', width: 1.25 },
      { key: 'pred', color: 'rgba(129,60,52,.9)', width: 1.15 }
    ];
    for (const s of series) {
      ctx.beginPath();
      points.forEach((p, i) => {
        const x = xFor(p.gen), y = yFor(p[s.key]);
        i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      });
      ctx.strokeStyle = s.color;
      ctx.lineWidth = s.width;
      ctx.stroke();
      const last = points[points.length - 1];
      if (last) {
        ctx.fillStyle = s.color;
        ctx.beginPath(); ctx.arc(xFor(last.gen), yFor(last[s.key]), 1.9, 0, TAU); ctx.fill();
      }
    }
    // event marks
    for (const ev of eco.events) {
      const x = xFor(ev.gen);
      ctx.strokeStyle = CAT_COLORS[ev.kind] + '88';
      ctx.setLineDash([1.5, 2]);
      ctx.lineWidth = 0.7;
      ctx.beginPath(); ctx.moveTo(x, padT); ctx.lineTo(x, h - padB); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = CAT_COLORS[ev.kind];
      ctx.font = '600 5px "JetBrains Mono", "Liberation Mono", monospace';
      ctx.textAlign = 'center';
      ctx.fillText(CAT_META[ev.kind].letter, x, padT - 3.5);
    }
    // playhead
    const cx = xFor(currentGen);
    ctx.strokeStyle = 'rgba(32,48,39,.45)';
    ctx.setLineDash([2, 3]);
    ctx.lineWidth = 0.7;
    ctx.beginPath(); ctx.moveTo(cx, padT - 1); ctx.lineTo(cx, h - padB + 1); ctx.stroke();
    ctx.setLineDash([]);
    // x endpoints
    ctx.fillStyle = 'rgba(32,48,39,.5)';
    ctx.font = '5.4px "JetBrains Mono", "Liberation Mono", monospace';
    ctx.textAlign = 'left';
    ctx.fillText('GEN 0', padL, h - 3);
    ctx.textAlign = 'right';
    ctx.fillText('GEN ' + target, w - padR, h - 3);
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(32,48,39,.58)';
    ctx.fillText('T+' + String(eco.tick).padStart(4, '0'), (padL + w - padR) / 2, h - 3);
  }

  render(eco, now, alpha, settings) {
    if (!this.w) this.resize();
    this.ensureBackground();
    const ctx = this.ctx;
    ctx.clearRect(0, 0, this.w, this.h);
    ctx.drawImage(this.bgCanvas, 0, 0, this.w, this.h);
    this.drawPlantLayer();
    ctx.drawImage(this.plantCanvas, 0, 0, this.w, this.h);
    const { map } = this;
    ctx.save();
    ctx.strokeStyle = 'rgba(32,48,39,.25)';
    ctx.lineWidth = 0.8;
    // re-ink the map edge above the plant cache
    ctx.strokeRect(map.x + 0.5, map.y + 0.5, map.w, map.h);
    ctx.restore();
    this.drawAnimals(eco, alpha, now);
    this.drawAtmosphere(eco, now);
    this.drawGlassEdge();
    this.drawLens();
    this.drawTimeline(eco, settings);
  }
}

