  newEcosystem() {
    return new Ecosystem({
      seed: this.settings.seed,
      mutation: this.settings.mutation / 100,
      regrowth: this.settings.regrowth,
      generations: this.settings.generations,
      intervals: { ...this.settings.intervals },
      refugia: this.settings.refugia
