  startRun(options = {}) {
    this.hideReport(true);
    this.eco = this.newEcosystem();
    this.settings.generations = this.eco.targetGenerations;
    this.paused = false;
    this.completed = false;
    this.finishedHandled = false;
    this.acc = 0;
    this.seenEvents = 0;
    this.currentEvent = null;
    this.eventListShown = 0;
    this.lastFrame = performance.now();
    this.lastCadenceTick = 0;
    this.cadence = [];
    this.els.seedInput.value = this.settings.seed;
    this.els.gensInput.value = this.settings.generations;
    this.els.lensToggle.checked = this.settings.lens;
    this.els.gridToggle.checked = this.settings.grid;
    this.els.refugiaToggle.checked = this.settings.refugia;
    this.els.reportReopen.hidden = true;
    this.els.eventBanner.classList.remove('is-visible');
    this.els.sideSeed.textContent = 'Seed ' + this.settings.seed;
    this.els.footSeed.textContent = this.settings.seed;
    this.els.plateSeedMark.textContent = 'Seed ' + this.settings.seed;
    this.els.seedSparkLabel.textContent = 'seed ' + this.settings.seed;
    this.els.genTotal.textContent = String(this.settings.generations).padStart(2, '0');
    this.els.gensInput.value = this.settings.generations;
    if (this.renderer) { this.renderer.focus = null; this.renderer.lastSeed = null; this.renderer.focusSet = false; }
    this.app.dataset.state = 'running';
    this.updateAllRangeFills();
    this.updateIntervalsUI();
    this.announce(`New observation with seed ${this.settings.seed}.`);
  }

  get ecoSettings() { return this.settings; }

  loop(now) {
    const dt = Math.min(0.12, (now - this.lastFrame) / 1000);
    this.lastFrame = now;
    if (!this.paused && !this.eco.done) {
      this.acc += dt * BASE_TICKS_PER_SECOND * this.settings.speed;
      let steps = 0;
      while (this.acc >= 1 && steps < 90 && !this.eco.done) {
        this.eco.step();
        this.acc -= 1;
        steps++;
      }
      if (steps) this.lastStepCount = steps;
      if (this.eco.events.length > this.seenEvents) {
        const ev = this.eco.events[this.seenEvents];
        this.seenEvents = this.eco.events.length;
        this.showEvent(ev);
      }
    }
    if (this.eco.done && !this.finishedHandled) this.finishRun();
    const alpha = this.paused || this.eco.done ? 1 : clamp(this.acc, 0, 1);
    this.renderer.render(this.eco, now, alpha, this.settings);
    if (now - this.uiLast > 100) {
      this.refreshUI(false);
      this.uiLast = now;
    }
    if (now - this.sparkLast > 420) {
      this.drawSparklines();
      this.sparkLast = now;
    }
    requestAnimationFrame(this.loop);
  }

  finishRun() {
    if (this.finishedHandled) return;
    this.finishedHandled = true;
    this.completed = true;
    this.paused = true;
    this.app.dataset.state = 'complete';
    this.els.statusText.textContent = 'Observation closed';
    this.els.reportReopen.hidden = false;
    this.updatePauseButton();
    this.announce(`Observation complete at generation ${this.eco.generation}. Opening field report.`);
    this.refreshUI(true);
    this.drawSparklines();
    setTimeout(() => {
      if (this.completed && !this.reportOpen) this.openReport();
    }, 900);
  }

  refreshUI(force = false) {
    if (!this.eco) return;
    const eco = this.eco;
    const nowGen = eco.generation;
    const target = eco.targetGenerations;
    const prog = clamp((eco.generation + (eco.done ? 0 : (eco.tick % GEN_TICKS) / GEN_TICKS)) / target, 0, 1);
    this.els.genNow.textContent = String(nowGen).padStart(2, '0');
    this.els.genTotal.textContent = String(target).padStart(2, '0');
    this.els.genProgress.style.width = (prog * 100).toFixed(2) + '%';
    this.els.floraCount.textContent = formatCount(eco.plantCells.length);
    this.els.preyCount.textContent = formatCount(eco.prey.length);
    this.els.predCount.textContent = formatCount(eco.pred.length);
    this.els.sideTick.textContent = 'tick ' + String(eco.tick).padStart(4, '0');
    const last = eco.records[eco.records.length - 1];
    if (last) {
      const ps = last.traits.prey, ts = last.traits.pred;
      this.els.preyTraitLine.textContent = ps.speed.mean === null ? 'spd — · vis —' : `spd ${toFixed(ps.speed.mean, 2)} · vis ${toFixed(ps.vision.mean, 1)}`;
      this.els.predTraitLine.textContent = ts.speed.mean === null ? 'spd — · vis —' : `spd ${toFixed(ts.speed.mean, 2)} · vis ${toFixed(ts.vision.mean, 1)}`;
    }
    const active = eco.active[eco.active.length - 1];
    let weather = 'Clemency';
    let weatherColor = getComputedStyle(document.documentElement).getPropertyValue('--flora').trim();
    if (active) {
      weather = CAT_META[active.kind].label;
      weatherColor = CAT_META[active.kind].color;
    } else if (this.currentEvent && this.eventBannerVisible) {
      weather = CAT_META[this.currentEvent.kind].label;
      weatherColor = CAT_META[this.currentEvent.kind].color;
    }
    this.els.weatherTag.textContent = weather;
    this.els.weatherDot.style.background = weatherColor;
    // field note
    let note;
    if (active) {
      note = CAT_META[active.kind].note;
    } else if (eco.prey.length === 0) {
      note = 'The grazers are gone. The kites look at an empty meadow, and the moss begins to close over their tracks.';
    } else if (eco.pred.length === 0) {
      note = 'The kites have vanished. Without their shadow, the grazers multiply as though the glass were endless.';
    } else if (eco.plantCoverage() < 0.07) {
      note = 'The moss keeps to its hollows. Grazers work the margins; the kites are thin as needles.';
    } else if (eco.prey.length > 600) {
      note = 'The grazers are many. Moss disappears beneath them; the kites have not yet caught the rhythm.';
    } else if (eco.prey.length < 45) {
      note = 'A hush in the grass. The surviving grazers move carefully; the kites must be patient.';
    } else if (nowGen < 3) {
      note = 'The meadow is young. Keep your eye on the small brown grazers; the kites will follow.';
    } else {
      note = 'Warmth favours the moss; appetite favours the swift. Nothing under the glass is still.';
    }
    if (this.els.fieldNoteText.textContent !== note) this.els.fieldNoteText.textContent = note;
    if (this.reportOpen && force) this.drawReportCharts();
    if (force) this.updateAllRangeFills();
    this.updateIntervalReadouts();
    this.updatePauseButton();
    if (!this.completed) {
      this.els.statusText.textContent = this.paused ? 'Field held' : 'Field active';
      this.app.dataset.state = this.paused ? 'paused' : 'running';
    } else {
      this.els.statusText.textContent = 'Observation closed';
      this.app.dataset.state = 'complete';
    }
  }

  updatePauseButton() {
    if (this.completed) {
      this.els.pauseLabel.textContent = 'Concluded';
      this.els.pauseBtn.disabled = true;
      this.els.pauseIcon.className = 'transport-icon pause';
      return;
    }
    this.els.pauseBtn.disabled = false;
    this.els.pauseLabel.textContent = this.paused ? 'Resume' : 'Hold';
    this.els.pauseIcon.className = this.paused ? 'transport-icon play' : 'transport-icon pause';
    this.els.pauseBtn.querySelector('kbd').textContent = 'SPACE';
  }

  togglePause() {
    if (this.completed) return;
    this.paused = !this.paused;
    this.app.dataset.state = this.paused ? 'paused' : 'running';
    this.refreshUI(true);
    this.announce(this.paused ? 'Observation held.' : 'Observation resumed.');
  }

  updateAllRangeFills() {
    const items = [
      [this.els.mutationRange, 0, 15],
      [this.els.regrowthRange, 0.4, 2.2],
      [this.els.droughtRange, 0, 20],
      [this.els.blightRange, 0, 20],
      [this.els.frostRange, 0, 20]
    ];
    for (const [input, min, max] of items) {
      if (!input) continue;
      const pct = clamp((+input.value - min) / (max - min), 0, 1) * 100;
      input.style.setProperty('--pct', pct.toFixed(2) + '%');
    }
  }

  updateIntervalsUI() {
    const eco = this.eco;
    if (!eco) return;
    const setCat = (kind, output, nextEl) => {
      const val = eco.intervals[kind];
      output.innerHTML = val > 0 ? `1 / ${val}<span class="readout-unit">gen</span>` : `off<span class="readout-unit">clemency</span>`;
      if (nextEl) {
        if (!val) nextEl.textContent = 'clemency';
        else {
          const next = eco.nextDueFor(kind);
          nextEl.textContent = Number.isFinite(next) ? 'next · gen ' + String(next).padStart(2, '0') : 'next —';
        }
      }
    };
    setCat('drought', this.els.droughtOut, this.els.droughtNext);
    setCat('blight', this.els.blightOut, this.els.blightNext);
    setCat('frost', this.els.frostOut, this.els.frostNext);
  }

  updateIntervalReadouts() { this.updateIntervalsUI(); }

  drawSparklines() {
    if (!this.eco) return;
    const eco = this.eco;
    const brass = '#e0c696';
    const flora = '#a3b174';
    const prey = '#d8a565';
    const pred = '#c87c6a';
    // seed fingerprint
    const fpRng = mulberry32(hashSeed('fingerprint-' + this.settings.seed));
    let last = 0.4;
    const fp = [];
    for (let i = 0; i < 32; i++) {
      last = clamp(last + (fpRng() - 0.5) * 0.33, 0.08, 0.92);
      fp.push(Math.sin(i * 0.63 + this.settings.seed * 0.017) * 0.12 + last);
    }
    drawSparkline(this.els.sparkSeed, fp, brass);
    // mutation effect = observed trait spread
    drawSparkline(this.els.sparkMutation, eco.telemetry.spread.map(v => v * 100), brass, { playhead: 1 });
    // food effect = plant cover
    drawSparkline(this.els.sparkRegrowth, eco.telemetry.plant, flora, { playhead: 1 });
    // generations = horizon; draw manually
    const gc = this.els.sparkGenerations;
    const gr = gc.getBoundingClientRect();
    if (gr.width) {
      const fit = fitCanvas(gc, gr.width, gr.height);
      const c = fit.ctx, w = fit.width, h = fit.height;
      c.clearRect(0, 0, w, h);
      c.strokeStyle = 'rgba(225,205,167,.17)'; c.lineWidth = .7;
      c.beginPath(); c.moveTo(0, h - 3.5); c.lineTo(w, h - 3.5); c.stroke();
      const progress = clamp(this.eco.generation / Math.max(1, this.eco.targetGenerations), 0, 1);
      const px = 2 + progress * (w - 4);
      c.strokeStyle = 'rgba(224,198,150,.68)'; c.lineWidth = 1;
      c.beginPath(); c.moveTo(2, h - 4); c.lineTo(px, h - 4); c.stroke();
      c.strokeStyle = 'rgba(224,198,150,.22)'; c.setLineDash([1.5, 2]);
      c.beginPath(); c.moveTo(px, h - 4); c.lineTo(w - 2, h - 4); c.stroke(); c.setLineDash([]);
      for (let i = 0; i <= 5; i++) {
        const tx = 2 + (i / 5) * (w - 4);
        c.strokeStyle = i / 5 <= progress ? 'rgba(224,198,150,.8)' : 'rgba(224,198,150,.2)';
        c.beginPath(); c.moveTo(tx, h - 6); c.lineTo(tx, h - 2); c.stroke();
      }
      c.fillStyle = brass; c.beginPath(); c.arc(px, h - 4, 1.7, 0, TAU); c.fill();
    }
    // speed cadence
    const cadence = this.cadence && this.cadence.length ? this.cadence.slice(-32) : [this.settings.speed * 2, this.settings.speed * 2];
    drawSparkline(this.els.sparkSpeed, cadence, brass);
    // catastrophes: schedule preview
    for (const kind of CAT_ORDER) {
      const color = CAT_COLORS[kind];
      const canvas = this.els['spark' + kind[0].toUpperCase() + kind.slice(1)];
      const due = eco.nextDueFor(kind);
      const interval = eco.intervals[kind];
      const target = Math.max(1, eco.targetGenerations);
      const vals = new Array(34).fill(0.04);
      if (interval > 0 && Number.isFinite(due)) {
        let gen = due;
        let guard = 0;
        while (gen <= target && guard++ < 12) {
          const idx = Math.round((gen / target) * (vals.length - 1));
          for (let k = -1; k <= 1; k++) {
            const ii = idx + k;
            if (ii >= 0 && ii < vals.length) vals[ii] = Math.max(vals[ii], 0.95 - Math.abs(k) * 0.3);
          }
          gen += interval;
        }
      }
      drawSparkline(canvas, vals, color, { playhead: eco.generation / Math.max(1, target) });
    }
    // species micro-traces
    drawSparkline(this.els.sparkFlora, eco.telemetry.plant, '#87995f');
    drawSparkline(this.els.sparkPrey, eco.telemetry.prey, '#b8783c');
    drawSparkline(this.els.sparkPred, eco.telemetry.pred, '#813c34');
    // cadence history
    const now = performance.now();
    if (now - this.cadenceLast > 320) {
      const delta = Math.max(0, eco.tick - this.lastCadenceTick);
      this.cadence.push(delta);
      if (this.cadence.length > 40) this.cadence.shift();
      this.lastCadenceTick = eco.tick;
      this.cadenceLast = now;
    }
  }

  showEvent(ev) {
    this.currentEvent = ev;
    this.eventBannerVisible = true;
    const meta = CAT_META[ev.kind];
    this.els.eventBanner.style.setProperty('--cat-color', meta.color);
    this.els.eventMark.innerHTML = GLYPH_SVG[ev.kind];
    this.els.eventKicker.textContent = `Weather event · generation ${String(ev.gen).padStart(2, '0')}`;
    this.els.eventName.textContent = meta.label;
    this.els.eventPhrase.textContent = meta.phrase;
    this.els.eventBanner.classList.add('is-visible');
    clearTimeout(this.eventTimeout);
    this.eventTimeout = setTimeout(() => {
      this.els.eventBanner.classList.remove('is-visible');
      this.eventBannerVisible = false;
    }, 6200);
    this.announce(`${meta.label} begins at generation ${ev.gen}. ${meta.note}`);
    this.updateIntervalsUI();
  }

  announce(text) {
    if (!this.els.announcer) return;
    this.els.announcer.textContent = '';
    window.setTimeout(() => { this.els.announcer.textContent = text; }, 30);
  }

  bindControls() {
    const handleSeedChange = () => {
      let value = Math.round(Number(this.els.seedInput.value) || 1);
      value = clamp(value, 1, 9999);
      this.els.seedInput.value = value;
      if (value !== this.settings.seed) {
        this.settings.seed = value;
        this.startRun();
      }
    };
    this.els.seedInput.addEventListener('change', handleSeedChange);
    this.els.seedInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); handleSeedChange(); this.els.seedInput.blur(); } });
    this.els.seedUp.addEventListener('click', () => { this.settings.seed = clamp((this.settings.seed % 9999) + 1, 1, 9999); if (this.completed) this.startRun(); else { this.els.seedInput.value = this.settings.seed; this.startRun(); } });
    this.els.seedDown.addEventListener('click', () => { this.settings.seed = this.settings.seed <= 1 ? 9999 : this.settings.seed - 1; this.startRun(); });
    this.els.seedRandom.addEventListener('click', () => this.newSeed());
    const handleGenerations = (raw) => {
      let value = clamp(Math.round(Number(raw) || this.settings.generations), 4, 60);
      this.settings.generations = value;
      this.els.gensInput.value = value;
      this.eco.setTargetGenerations(value);
      if (value <= this.eco.generation) {
        this.eco.done = true;
        this.finishRun();
      } else if (this.completed) {
        this.completed = false;
        this.finishedHandled = false;
        this.paused = false;
        this.hideReport(true);
        this.app.dataset.state = 'running';
      }
      this.els.genTotal.textContent = String(value).padStart(2, '0');
      this.updateAllRangeFills();
      this.refreshUI(true);
    };
    this.els.gensInput.addEventListener('change', () => handleGenerations(this.els.gensInput.value));
    this.els.gensInput.addEventListener('keydown', e => { if (e.key === 'Enter') { e.preventDefault(); handleGenerations(this.els.gensInput.value); this.els.gensInput.blur(); } });
    this.els.gensUp.addEventListener('click', () => handleGenerations(this.settings.generations + 1));
    this.els.gensDown.addEventListener('click', () => handleGenerations(this.settings.generations - 1));
    const bindRange = (input, onInput, formatter) => {
      const handler = () => {
        const val = +input.value;
        this.updateAllRangeFills();
        onInput(val);
        if (formatter) formatter(val);
      };
      input.addEventListener('input', handler);
      handler();
    };
    bindRange(this.els.mutationRange, v => {
      this.settings.mutation = v;
      if (this.eco) this.eco.mutation = v / 100;
      this.els.mutationOut.innerHTML = `${v.toFixed(1)}<span class="readout-unit">% per gene</span>`;
    });
    bindRange(this.els.regrowthRange, v => {
      this.settings.regrowth = v;
      if (this.eco) this.eco.regrowth = v;
      this.els.regrowthOut.innerHTML = `${v.toFixed(2)}<span class="readout-unit">×</span>`;
    });
    for (const kind of CAT_ORDER) {
      const input = this.els[kind + 'Range'];
      bindRange(input, v => {
        this.settings.intervals[kind] = Math.round(v);
        if (this.eco) {
          this.eco.setCatastropheInterval(kind, v);
          this.updateIntervalsUI();
          this.drawSparklines();
        }
      });
    }
    this.els.pauseBtn.addEventListener('click', () => this.togglePause());
    this.els.restartBtn.addEventListener('click', () => this.startRun());
    this.els.lensToggle.addEventListener('change', () => {
      this.settings.lens = this.els.lensToggle.checked;
      if (this.renderer) this.renderer.focusSet = false;
      this.announce(this.settings.lens ? 'Loupe lowered.' : 'Loupe raised.');
    });
    this.els.gridToggle.addEventListener('change', () => {
      this.settings.grid = this.els.gridToggle.checked;
      if (this.renderer) this.renderer.lastGrid = null;
    });
    this.els.refugiaToggle.addEventListener('change', () => {
      this.settings.refugia = this.els.refugiaToggle.checked;
      if (this.eco) this.eco.refugia = this.settings.refugia;
      this.announce(this.settings.refugia ? 'Refugia active.' : 'Refugia closed.');
    });
    this.els.drawerCollapse.addEventListener('click', () => this.toggleDrawer());
    this.els.drawerSpine.addEventListener('click', () => this.toggleDrawer(true));
    this.els.drawerFab.addEventListener('click', () => this.setMobileDrawer(true));
    this.els.drawerScrim.addEventListener('click', () => this.setMobileDrawer(false));
    this.els.reportReopen.addEventListener('click', () => this.openReport());
    this.els.speedOut.innerHTML = `${this.settings.speed.toFixed(1)}<span class="readout-unit">×</span>`;
    this.els.speedValue.innerHTML = `${this.settings.speed.toFixed(1)}<small>×</small>`;
    this.updateDial(this.settings.speed);
    this.updateAllRangeFills();
    this.updateIntervalsUI();
    if (!this.pointerFine) {
      this.settings.lens = false;
      this.els.lensToggle.checked = false;
    }
  }

  updateDial(value) {
    const min = 0.25, max = 8;
    const angle = -135 + ((value - min) / (max - min)) * 270;
    this.els.speedNeedle.style.transform = `rotate(${angle}deg)`;
    this.els.speedDial.setAttribute('aria-valuenow', value.toFixed(2));
    this.els.speedDial.setAttribute('aria-valuetext', `${value.toFixed(2)} times speed, roughly ${Math.round(value * BASE_TICKS_PER_SECOND)} ticks per second`);
    this.els.speedOut.innerHTML = `${value.toFixed(1)}<span class="readout-unit">×</span>`;
    this.els.speedValue.innerHTML = `${value.toFixed(1)}<small>×</small>`;
    this.els.speedUnit.textContent = `${Math.round(value * BASE_TICKS_PER_SECOND)} ticks / sec · 1 gen ≈ ${(GEN_TICKS / (BASE_TICKS_PER_SECOND * value)).toFixed(1)} s`;
  }

  setSpeed(value) {
    const v = clamp(Math.round(value * 4) / 4, 0.25, 8);
    this.settings.speed = v;
    this.updateDial(v);
  }

  bindDial() {
    const dial = this.els.speedDial;
    let dragging = false;
    const valueFromPointer = e => {
      const r = dial.getBoundingClientRect();
      const dx = e.clientX - (r.left + r.width / 2);
      const dy = e.clientY - (r.top + r.height / 2);
      if (Math.hypot(dx, dy) < 9) return null;
      let deg = Math.atan2(dx, -dy) * 180 / Math.PI;
      if (deg < 0) deg += 360;
      let ext = deg < 225 ? deg + 360 : deg;
      ext = clamp(ext, 225, 495);
      const pct = (ext - 225) / 270;
      return 0.25 + pct * (8 - 0.25);
    };
    dial.addEventListener('pointerdown', e => {
      dragging = true;
      dial.setPointerCapture(e.pointerId);
      const v = valueFromPointer(e);
      if (v !== null) this.setSpeed(v);
      e.preventDefault();
    });
    dial.addEventListener('pointermove', e => {
      if (!dragging) return;
      const v = valueFromPointer(e);
      if (v !== null) this.setSpeed(v);
    });
    const stop = e => { dragging = false; try { dial.releasePointerCapture(e.pointerId); } catch (_) {} };
    dial.addEventListener('pointerup', stop);
    dial.addEventListener('pointercancel', stop);
    dial.addEventListener('wheel', e => {
      e.preventDefault();
      this.setSpeed(this.settings.speed + (e.deltaY < 0 ? 0.25 : -0.25));
    }, { passive: false });
    dial.addEventListener('keydown', e => {
      let handled = true;
      const step = e.shiftKey ? 1 : 0.25;
      switch (e.key) {
        case 'ArrowUp': case 'ArrowRight': this.setSpeed(this.settings.speed + step); break;
        case 'ArrowDown': case 'ArrowLeft': this.setSpeed(this.settings.speed - step); break;
        case 'PageUp': this.setSpeed(this.settings.speed + 1); break;
        case 'PageDown': this.setSpeed(this.settings.speed - 1); break;
        case 'Home': this.setSpeed(0.25); break;
        case 'End': this.setSpeed(8); break;
        default: handled = false;
      }
      if (handled) e.preventDefault();
    });
  }

  newSeed() {
    let candidate = this.settings.seed;
    let guard = 0;
    while (candidate === this.settings.seed && guard++ < 20) {
      candidate = 1000 + Math.floor(Math.random() * 9000);
    }
    this.settings.seed = candidate;
    this.startRun();
    this.announce('A new seed has been drawn.');
  }

  toggleDrawer(forceOpen = false) {
    if (window.innerWidth <= 880) {
      this.setMobileDrawer(!this.app.classList.contains('mobile-drawer-open'));
      return;
    }
    const collapsed = this.app.classList.toggle('drawer-collapsed', !forceOpen);
    this.els.drawerCollapse.setAttribute('aria-label', collapsed ? 'Expand instrument drawer' : 'Collapse instrument drawer');
    this.els.drawerCollapse.title = collapsed ? 'Expand instruments (D)' : 'Collapse instruments (D)';
    setTimeout(() => { if (this.renderer) this.renderer.resize(); }, 420);
  }

  setMobileDrawer(open) {
    this.app.classList.toggle('mobile-drawer-open', open);
    this.els.drawerFab.setAttribute('aria-expanded', String(open));
    if (open) {
      const first = this.els.drawer.querySelector('button, input, [tabindex]');
      if (first) first.focus({ preventScroll: true });
    }
  }

  bindTooltip() {
    const tip = this.els.tooltip;
    const show = (target, sourceEvent) => {
      const text = target.getAttribute('data-tip');
      if (!text) return;
      this.tooltipTarget = target;
      tip.textContent = text;
      tip.classList.add('is-visible');
      tip.setAttribute('aria-hidden', 'false');
      const r = target.getBoundingClientRect();
      tip.style.left = '0px'; tip.style.top = '0px';
      requestAnimationFrame(() => {
        const tr = tip.getBoundingClientRect();
        let x = r.left + r.width / 2 - tr.width / 2;
        x = clamp(x, 10, window.innerWidth - tr.width - 10);
        let y = r.top - tr.height - 10;
        let side = 'above';
        if (y < 48) { y = r.bottom + 10; side = 'below'; }
        tip.style.left = x + 'px';
        tip.style.top = y + 'px';
        tip.dataset.side = side;
      });
    };
    const hide = () => {
      tip.classList.remove('is-visible');
      tip.setAttribute('aria-hidden', 'true');
      this.tooltipTarget = null;
    };
    document.addEventListener('mouseover', e => {
      const target = e.target.closest('[data-tip]');
      if (!target) return;
      if (target.contains(e.relatedTarget)) return;
      show(target, e);
    });
    document.addEventListener('mouseout', e => {
      const target = e.target.closest('[data-tip]');
      if (!target) return;
      if (target.contains(e.relatedTarget)) return;
      if (target.contains(document.activeElement)) return;
      hide();
    });
    document.addEventListener('focusin', e => {
      const target = e.target.closest('[data-tip]');
      if (target) show(target, e);
    });
    document.addEventListener('focusout', e => {
      const target = e.target.closest('[data-tip]');
      if (!target) return;
      if (target.contains(e.relatedTarget)) return;
      hide();
    });
    window.addEventListener('scroll', hide, { passive: true });
  }

  bindKeyboard() {
    document.addEventListener('keydown', e => {
      if (this.reportOpen) {
        if (e.key === 'Escape') { e.preventDefault(); this.closeReport(); return; }
        if (e.key === 'Tab') this.trapReportFocus(e);
        return;
      }
      const tag = (e.target.tagName || '').toLowerCase();
      const editable = tag === 'input' || tag === 'textarea' || tag === 'select' || e.target.isContentEditable;
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      if (editable) return;
      if (e.code === 'Space') {
        e.preventDefault();
        this.togglePause();
      } else if (e.key.toLowerCase() === 'r') {
        this.startRun();
      } else if (e.key.toLowerCase() === 'n') {
        this.newSeed();
      } else if (e.key.toLowerCase() === 'l') {
        if (!this.pointerFine) return;
        this.settings.lens = !this.settings.lens;
        this.els.lensToggle.checked = this.settings.lens;
        this.renderer.focusSet = false;
      } else if (e.key.toLowerCase() === 'g') {
        this.settings.grid = !this.settings.grid;
        this.els.gridToggle.checked = this.settings.grid;
        this.renderer.lastGrid = null;
      } else if (e.key.toLowerCase() === 'd') {
        this.toggleDrawer();
      } else if (e.key === 'Escape') {
        if (this.app.classList.contains('mobile-drawer-open')) this.setMobileDrawer(false);
        else if (this.app.classList.contains('drawer-collapsed')) this.toggleDrawer(true);
      }
    });
    window.addEventListener('resize', () => {
      if (window.innerWidth > 880) this.app.classList.remove('mobile-drawer-open');
      if (this.reportOpen) this.drawReportCharts();
    });
    if (this.els.reportReopen) this.els.reportReopen.addEventListener('click', () => this.openReport());
  }

  bindReport() {
    this.els.reportClose.addEventListener('click', () => this.closeReport());
    this.els.reportInspect.addEventListener('click', () => this.closeReport());
    this.els.reportReplay.addEventListener('click', () => { this.closeReport(true); this.startRun(); });
    this.els.reportNew.addEventListener('click', () => { this.closeReport(true); this.newSeed(); });
    this.els.populationChart.addEventListener('pointermove', e => this.onPopulationHover(e));
    this.els.populationChart.addEventListener('pointerleave', () => {
      this.reportHoverGen = null;
      this.els.chartHover.hidden = true;
      this.drawPopulationChart();
    });
    this.els.reportOverlay.addEventListener('pointerdown', e => {
      if (e.target === this.els.reportOverlay) this.closeReport();
    });
  }

  openReport() {
    if (!this.eco) return;
    this.reportOpen = true;
    this.reportRenderToken++;
    this.focusBeforeReport = document.activeElement;
    this.els.reportSeedMeta.textContent = 'SEED ' + this.eco.seed;
    this.els.reportGenMeta.textContent = this.eco.generation + ' GENERATIONS';
    this.els.reportDateMeta.textContent = 'OBSERVED FROM LIFE';
    this.els.reportSubtitle.textContent = `A closed meadow, concluded at generation ${this.eco.generation}.`;
    this.populateReport();
    this.els.reportOverlay.removeAttribute('inert');
    this.els.reportOverlay.setAttribute('aria-hidden', 'false');
    this.els.reportOverlay.classList.add('is-open');
    this.els.reportReopen.hidden = true;
    this.els.reportScroll.scrollTop = 0;
    document.body.classList.add('report-open');
    setTimeout(() => {
      this.drawReportCharts();
      const close = this.els.reportClose;
      if (close) close.focus({ preventScroll: true });
    }, 120);
  }

  closeReport(instant = false) {
    if (!this.reportOpen) return;
    this.reportOpen = false;
    this.els.reportOverlay.classList.remove('is-open');
    this.els.reportOverlay.setAttribute('aria-hidden', 'true');
    this.els.reportOverlay.setAttribute('inert', '');
    document.body.classList.remove('report-open');
    if (this.completed) this.els.reportReopen.hidden = false;
    if (!instant && this.focusBeforeReport && this.focusBeforeReport.focus) {
      setTimeout(() => this.focusBeforeReport.focus({ preventScroll: true }), 40);
    }
  }

  hideReport(instant = false) {
    if (this.reportOpen) this.closeReport(true);
    this.els.reportOverlay.classList.remove('is-open');
    this.els.reportOverlay.setAttribute('aria-hidden', 'true');
    this.els.reportOverlay.setAttribute('inert', '');
    this.els.reportReopen.hidden = true;
  }

  trapReportFocus(e) {
    const focusables = [...this.els.reportOverlay.querySelectorAll('button,[href],input,select,textarea,[tabindex]:not([tabindex="-1"])')]
      .filter(el => !el.disabled && el.offsetParent !== null);
    if (!focusables.length) return;
    const first = focusables[0], last = focusables[focusables.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }

  getFinalRecord() {
    return this.eco.records[this.eco.records.length - 1] || { plant: 0, prey: 0, pred: 0, traits: { prey: {}, pred: {} } };
  }

  populateReport() {
    const eco = this.eco;
    const last = this.getFinalRecord();
    const events = eco.events;
    const refs = eco.refugiaEvents || [];
    const totalBirths = eco.births.prey + eco.births.pred;
    const speciesAlive = [last.plant > 0, last.prey > 0, last.pred > 0].filter(Boolean).length;
    this.els.reportSummary.innerHTML = `
      <div class="summary-stat"><span class="label">Generations</span><span class="value">${String(eco.generation).padStart(2, '0')}<small>observed</small></span></div>
      <div class="summary-stat"><span class="label">Births</span><span class="value">${formatCount(totalBirths)}<small>new lives</small></span></div>
      <div class="summary-stat"><span class="label">Weather</span><span class="value">${String(events.length).padStart(2, '0')}<small>events</small></span></div>
      <div class="summary-stat"><span class="label">Lines at close</span><span class="value">${speciesAlive}<small>/ 3</small></span></div>
      <div class="summary-census"><span class="label">Final census</span><div class="census-line">
        <span class="census-item" style="--species:var(--flora)">${formatCount(last.plant)}<span>moss</span></span>
        <span class="census-item" style="--species:var(--prey)">${formatCount(last.prey)}<span>grazers</span></span>
        <span class="census-item" style="--species:var(--pred)">${formatCount(last.pred)}<span>kites</span></span>
      </div></div>
    `;
    if (!events.length) {
      this.els.eventLedger.innerHTML = '<li><span class="empty-ledger">No weather reached the glass. The meadow was left to its own devices.</span></li>';
    } else {
      this.els.eventLedger.innerHTML = events.map(ev => {
        const meta = CAT_META[ev.kind];
        return `<li style="--cat-color:${meta.color}">
          <span class="ledger-mark">${meta.letter}</span>
          <span><span class="ledger-name">${meta.label}</span><span class="ledger-detail">${meta.phrase}</span></span>
          <span class="ledger-gen">GEN ${String(ev.gen).padStart(2, '0')}</span>
        </li>`;
      }).join('');
    }
    const refugiaText = refs.length
      ? `${refs.length} refugia stirring${refs.length > 1 ? 's' : ''}. Dormant life was coaxed back.`
      : 'No refugia were needed. The seed held.';
    this.els.eventPanelNote.innerHTML = refs.length
      ? `${refs.length} REFUGIUM STIRRING${refs.length > 1 ? 'S' : ''}<br>Dormant life was coaxed back after a line was lost.`
      : 'NO REFUGIA NEEDED<br>The seed held without the keeper\'s hand.';
    this.els.reportFooterNote.textContent = last.prey === 0 || last.pred === 0
      ? 'Something has left the glass. The charts keep the shape of its going.'
      : 'Every mark is drawn from the seed. A quiet world is still a world.';
    this.buildDriftBlocks();
    this.drawReportCharts();
  }

  buildDriftBlocks() {
    const speciesInfo = [
      ['prey', 'Meadow grazer', 'Herbivora campestris', GLYPH_SVG.prey, '#b8783c'],
      ['pred', 'Ember kite', 'Milvus rubra', GLYPH_SVG.pred, '#813c34']
    ];
    const last = this.getFinalRecord();
    this.els.driftBlocks.innerHTML = speciesInfo.map(([species, name, latin, glyph, color]) => {
      const alive = species === 'prey' ? last.prey : last.pred;
      return `<div class="drift-block" style="--sp-color:${color}">
        <div class="drift-species">
          <span class="ds-glyph">${glyph}</span>
          <h4>${name}</h4><span class="ds-latin">${latin}</span>
          <span class="ds-note">${alive ? formatCount(alive) + ' alive at close' : 'line lost before close'}</span>
        </div>
        <div class="drift-grid">
          ${GENE_KEYS.map(key => `<div class="drift-card" data-species="${species}" data-gene="${key}" style="--sp-color:${color}">
            <div class="drift-card-head"><strong>${GENE_META[key].short} · ${GENE_META[key].label}</strong><span>${GENE_META[key].unit}</span></div>
            <canvas role="img" aria-label="${name} ${GENE_META[key].label} drift, mean and one standard deviation"></canvas>
            <div class="drift-card-foot"><b>${this.geneStatText(species, key, 'mean')}</b><span>± ${this.geneStatText(species, key, 'sd')}</span></div>
          </div>`).join('')}
        </div>
      </div>`;
    }).join('');
  }

  geneStatText(species, key, field) {
    const rec = this.getFinalRecord();
    const st = rec.traits && rec.traits[species] && rec.traits[species][key];
    if (!st || st[field] === null || st[field] === undefined) return '—';
    const digits = key === 'repro' ? 0 : key === 'metabolism' ? 2 : 2;
    return toFixed(st[field], digits);
  }

  reportGeometry() {
    const rect = this.els.populationChart.getBoundingClientRect();
    return { w: rect.width, h: rect.height };
  }

  drawReportCharts() {
    if (!this.reportOpen) return;
    this.drawPopulationChart();
    const cards = this.els.driftBlocks.querySelectorAll('.drift-card');
    for (const card of cards) {
      const species = card.dataset.species;
      const gene = card.dataset.gene;
      const canvas = card.querySelector('canvas');
      this.drawDriftChart(canvas, species, gene);
    }
  }

  drawPopulationChart() {
    const canvas = this.els.populationChart;
    const rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const fit = fitCanvas(canvas, rect.width, rect.height, dpr);
    const ctx = fit.ctx;
    const w = fit.width, h = fit.height;
    ctx.clearRect(0, 0, w, h);
    const records = this.eco.records;
    if (records.length < 1) return;
    const target = Math.max(this.eco.generation, this.eco.targetGenerations);
    const pad = { l: 42, r: 17, t: 25, b: 24 };
    const plotW = w - pad.l - pad.r;
    const plotH = h - pad.t - pad.b;
    const xFor = gen => pad.l + (gen / target) * plotW;
    let maxVal = 10;
    for (const r of records) maxVal = Math.max(maxVal, r.plant, r.prey, r.pred);
    const maxExp = Math.max(1, Math.ceil(Math.log10(maxVal)));
    const yFor = value => {
      const t = Math.log10(Math.max(1, value)) / maxExp;
      return pad.t + (1 - t) * plotH;
    };
    // panel wash
    ctx.fillStyle = 'rgba(245,238,225,.20)';
    ctx.fillRect(pad.l, pad.t, plotW, plotH);
    // horizontal rules + labels
    ctx.font = '7px "JetBrains Mono", "Liberation Mono", monospace';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    for (let e = 0; e <= maxExp; e++) {
      const y = pad.t + (1 - e / maxExp) * plotH;
      ctx.strokeStyle = e === 0 ? 'rgba(32,48,39,.28)' : 'rgba(32,48,39,.10)';
      ctx.lineWidth = e === 0 ? 0.8 : 0.6;
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(w - pad.r, y); ctx.stroke();
      ctx.fillStyle = 'rgba(32,48,39,.5)';
      const label = e === 0 ? '1' : e === 1 ? '10' : e === 2 ? '100' : e === 3 ? '1k' : e === 4 ? '10k' : '100k';
      ctx.fillText(label, pad.l - 9, y);
    }
    // x ticks
    const xStep = target <= 20 ? 2 : target <= 40 ? 5 : 10;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillStyle = 'rgba(32,48,39,.5)';
    for (let g = 0; g <= target; g += xStep) {
      const x = xFor(g);
      ctx.strokeStyle = 'rgba(32,48,39,.08)';
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + plotH); ctx.stroke();
      ctx.fillText(String(g), x, h - pad.b + 7);
    }
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(32,48,39,.46)';
    ctx.font = '6px "JetBrains Mono", "Liberation Mono", monospace';
    ctx.fillText('GENERATION', pad.l + plotW / 2, h - 9);
    // event markers
    for (const ev of this.eco.events) {
      const x = xFor(ev.gen);
      const meta = CAT_META[ev.kind];
      ctx.strokeStyle = meta.color + '77';
      ctx.lineWidth = 0.8;
      ctx.setLineDash([2, 3]);
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + plotH); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = meta.color;
      ctx.beginPath(); ctx.arc(x, pad.t - 7, 5.7, 0, TAU); ctx.fill();
      ctx.fillStyle = '#f3ecdc';
      ctx.font = '600 6px "JetBrains Mono", monospace';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText(meta.letter, x, pad.t - 6.5);
      ctx.fillStyle = meta.color;
      ctx.font = '5.5px "JetBrains Mono", monospace';
      ctx.textBaseline = 'top';
      ctx.fillText('G' + ev.gen, x, pad.t - 2);
    }
    // lines
    const lines = [
      { key: 'plant', color: COLORS.flora, width: 1.25 },
      { key: 'prey', color: COLORS.prey, width: 1.55 },
      { key: 'pred', color: COLORS.pred, width: 1.45 }
    ];
    for (const line of lines) {
      ctx.beginPath();
      records.forEach((r, i) => {
        const x = xFor(r.gen), y = yFor(r[line.key]);
        i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      });
      ctx.strokeStyle = line.color;
      ctx.lineWidth = line.width;
      ctx.lineJoin = 'round';
      ctx.stroke();
      const lastR = records[records.length - 1];
      const lx = xFor(lastR.gen), ly = yFor(lastR[line.key]);
      ctx.fillStyle = COLORS.paperHi;
      ctx.beginPath(); ctx.arc(lx, ly, 2.8, 0, TAU); ctx.fill();
      ctx.strokeStyle = line.color; ctx.lineWidth = 1.3; ctx.stroke();
      ctx.fillStyle = line.color;
      ctx.beginPath(); ctx.arc(lx, ly, 1.15, 0, TAU); ctx.fill();
    }
    // hover guide
    if (this.reportHoverGen !== null) {
      const x = xFor(this.reportHoverGen);
      ctx.strokeStyle = 'rgba(32,48,39,.44)';
      ctx.lineWidth = 0.8;
      ctx.setLineDash([2, 3]);
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + plotH); ctx.stroke();
      ctx.setLineDash([]);
      const rec = records.find(r => r.gen === this.reportHoverGen);
      if (rec) {
        for (const line of lines) {
          ctx.fillStyle = COLORS.paper;
          ctx.strokeStyle = line.color;
          ctx.lineWidth = 1;
          ctx.beginPath(); ctx.arc(x, yFor(rec[line.key]), 2.5, 0, TAU); ctx.fill(); ctx.stroke();
        }
      }
    }
    this.els.populationChart.setAttribute('aria-label', `Population curve. Final counts: ${this.eco.plantCells.length} moss, ${this.eco.prey.length} grazers, ${this.eco.pred.length} kites.`);
  }

  onPopulationHover(e) {
    const canvas = this.els.populationChart;
    const r = canvas.getBoundingClientRect();
    const x = e.clientX - r.left;
    const padL = 42, padR = 17;
    const plotW = r.width - padL - padR;
    if (x < padL || x > r.width - padR) {
      this.reportHoverGen = null;
      this.els.chartHover.hidden = true;
      this.drawPopulationChart();
      return;
    }
    const target = Math.max(this.eco.generation, this.eco.targetGenerations);
    const fraction = clamp((x - padL) / plotW, 0, 1);
    const gen = Math.round(fraction * target);
    const rec = this.eco.records.find(rr => rr.gen === gen) || this.eco.records[this.eco.records.length - 1];
    if (!rec) return;
    this.reportHoverGen = rec.gen;
    const ev = this.eco.events.find(ev => ev.gen === rec.gen);
    const hover = this.els.chartHover;
    hover.innerHTML = `<div class="ct-gen">Generation ${String(rec.gen).padStart(2, '0')}</div>
      <div class="ct-row" style="--species:var(--flora)"><b><i></i>moss</b><span>${formatCount(rec.plant)}</span></div>
      <div class="ct-row" style="--species:var(--prey)"><b><i></i>grazer</b><span>${formatCount(rec.prey)}</span></div>
      <div class="ct-row" style="--species:var(--pred)"><b><i></i>kite</b><span>${formatCount(rec.pred)}</span></div>
      ${ev ? `<div class="ct-event">${CAT_META[ev.kind].label} · ${CAT_META[ev.kind].phrase}</div>` : ''}`;
    hover.hidden = false;
    const hr = hover.getBoundingClientRect();
    let left = x + 13;
    if (left + hr.width > r.width - 5) left = x - hr.width - 13;
    const top = clamp(e.clientY - r.top - 20, 4, r.height - hr.height - 6);
    hover.style.left = left + 'px';
    hover.style.top = top + 'px';
    this.drawPopulationChart();
  }

  drawDriftChart(canvas, species, key) {
    const rect = canvas.getBoundingClientRect();
    if (!rect.width || !rect.height) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    const fit = fitCanvas(canvas, rect.width, rect.height, dpr);
    const ctx = fit.ctx;
    const w = fit.width, h = fit.height;
    ctx.clearRect(0, 0, w, h);
    const records = this.eco.records;
    const color = species === 'prey' ? COLORS.prey : COLORS.pred;
    const target = Math.max(this.eco.generation, 1);
    const pad = { l: 7, r: 7, t: 12, b: 8 };
    const plotW = w - pad.l - pad.r;
    const plotH = h - pad.t - pad.b;
    const valid = records.map(r => r.traits && r.traits[species] && r.traits[species][key]).map(s => s && s.mean !== null ? s : null);
    if (!valid.some(Boolean)) {
      ctx.fillStyle = 'rgba(32,48,39,.42)';
      ctx.font = 'italic 9px "Iowan Old Style", "Palatino Linotype", Georgia, serif';
      ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
      ctx.fillText('line not observed', w / 2, h / 2);
      return;
    }
    let min = Infinity, max = -Infinity;
    for (const st of valid) {
      if (!st) continue;
      min = Math.min(min, st.mean - (st.sd || 0));
      max = Math.max(max, st.mean + (st.sd || 0));
    }
    const span = Math.max(0.0001, max - min);
    min -= span * 0.10;
    max += span * 0.10;
    const xFor = gen => pad.l + (gen / target) * plotW;
    const yFor = v => pad.t + (1 - (v - min) / (max - min)) * plotH;
    // grid
    ctx.strokeStyle = 'rgba(32,48,39,.08)';
    ctx.lineWidth = 0.5;
    for (let i = 0; i <= 2; i++) {
      const y = pad.t + (i / 2) * plotH;
      ctx.beginPath(); ctx.moveTo(pad.l, y); ctx.lineTo(w - pad.r, y); ctx.stroke();
    }
    // event marks
    for (const ev of this.eco.events) {
      const x = xFor(ev.gen);
      ctx.strokeStyle = CAT_COLORS[ev.kind] + '35';
      ctx.lineWidth = 0.6;
      ctx.setLineDash([1, 3]);
      ctx.beginPath(); ctx.moveTo(x, pad.t); ctx.lineTo(x, pad.t + plotH); ctx.stroke();
      ctx.setLineDash([]);
    }
    // band
    const segments = [];
    let current = [];
    for (let i = 0; i < records.length; i++) {
      const st = valid[i];
      if (st) current.push({ gen: records[i].gen, st });
      else if (current.length) { segments.push(current); current = []; }
    }
    if (current.length) segments.push(current);
    for (const seg of segments) {
      if (seg.length < 2) continue;
      ctx.beginPath();
      seg.forEach((p, i) => {
        const x = xFor(p.gen), y = yFor(p.st.mean + (p.st.sd || 0));
        i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      });
      for (let i = seg.length - 1; i >= 0; i--) {
        const p = seg[i];
        ctx.lineTo(xFor(p.gen), yFor(p.st.mean - (p.st.sd || 0)));
      }
      ctx.closePath();
      ctx.fillStyle = color + '25';
      ctx.fill();
    }
    // mean
    for (const seg of segments) {
      ctx.beginPath();
      seg.forEach((p, i) => {
        const x = xFor(p.gen), y = yFor(p.st.mean);
        i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
      });
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.3;
      ctx.lineJoin = 'round';
      ctx.stroke();
      const last = seg[seg.length - 1];
      ctx.fillStyle = COLORS.paperHi;
      ctx.beginPath(); ctx.arc(xFor(last.gen), yFor(last.st.mean), 2.5, 0, TAU); ctx.fill();
      ctx.strokeStyle = color; ctx.lineWidth = 1.1; ctx.stroke();
      ctx.fillStyle = color;
      ctx.beginPath(); ctx.arc(xFor(last.gen), yFor(last.st.mean), 1, 0, TAU); ctx.fill();
    }
    ctx.fillStyle = 'rgba(32,48,39,.45)';
